namespace BatchRenameStudio.Core;

/// <summary>Which part of the file name the steps operate on.</summary>
public enum ApplyTo
{
    /// <summary>Steps operate on the base name only (extension handled separately).</summary>
    Name,

    /// <summary>Steps operate on the whole file name, extension included.</summary>
    NameAndExtension,
}

/// <summary>Processing order of the files in the folder.</summary>
public enum SortMode
{
    /// <summary>Ordinal (codepoint) ascending, case sensitive.</summary>
    Name,

    /// <summary>Filesystem creation timestamp, ascending.</summary>
    Created,

    /// <summary>Filesystem last-write timestamp, ascending.</summary>
    Modified,
}

/// <summary>The kind of transformation a step performs.</summary>
public enum StepOp
{
    Replace,
    Insert,
    Remove,
    Sequence,
    Case,
    Extension,
}

/// <summary>Where an <see cref="StepOp.Insert"/> or <see cref="StepOp.Sequence"/> step places its text.</summary>
public enum Position
{
    Prefix,
    Suffix,

    /// <summary>Insert at a 0-based character index (insert only).</summary>
    Index,
}

/// <summary>Casing transformation applied by a <see cref="StepOp.Case"/> step.</summary>
public enum CaseMode
{
    Upper,
    Lower,
    Title,
}

/// <summary>Extension transformation applied by an <see cref="StepOp.Extension"/> step.</summary>
public enum ExtensionMode
{
    Lower,
    Upper,
    Set,
}

/// <summary>
/// One transformation step. A single flat type covers every op, mirroring the
/// untagged-union shape of the rules JSON. Only the fields relevant to
/// <see cref="Op"/> are read; the rest keep their defaults.
/// </summary>
public sealed class RuleStep
{
    public StepOp Op { get; set; } = StepOp.Replace;

    // replace
    public string Find { get; set; } = string.Empty;
    public string ReplaceWith { get; set; } = string.Empty;
    public bool UseRegex { get; set; }
    public bool IgnoreCase { get; set; }

    // insert
    public string Text { get; set; } = string.Empty;
    public Position Position { get; set; } = Position.Prefix;
    public int Index { get; set; }

    // remove
    public int From { get; set; }
    public int Count { get; set; }

    // sequence
    public string Pattern { get; set; } = "{n:000}_";
    public int Start { get; set; } = 1;
    public int Step { get; set; } = 1;

    // case
    public CaseMode CaseMode { get; set; } = CaseMode.Lower;

    // extension
    public ExtensionMode ExtensionMode { get; set; } = ExtensionMode.Lower;
    public string Value { get; set; } = string.Empty;

    public RuleStep Clone() => (RuleStep)MemberwiseClone();

    /// <summary>Short human-readable form used by the rule list in the GUI.</summary>
    public string Describe() => Op switch
    {
        StepOp.Replace => $"replace  \"{Find}\" -> \"{ReplaceWith}\"" +
                          (UseRegex ? "  [regex]" : string.Empty) +
                          (IgnoreCase ? "  [ignore case]" : string.Empty),
        StepOp.Insert => Position == Position.Index
            ? $"insert  \"{Text}\"  at index {Index}"
            : $"insert  \"{Text}\"  as {Position.ToString().ToLowerInvariant()}",
        StepOp.Remove => $"remove  {Count} char(s) from index {From}",
        StepOp.Sequence => $"sequence  \"{Pattern}\"  start {Start} step {Step}  as {Position.ToString().ToLowerInvariant()}",
        StepOp.Case => $"case  {CaseMode.ToString().ToLowerInvariant()}",
        StepOp.Extension => ExtensionMode == ExtensionMode.Set
            ? $"extension  set \"{Value}\""
            : $"extension  {ExtensionMode.ToString().ToLowerInvariant()}",
        _ => Op.ToString(),
    };
}

/// <summary>A complete rule set: scope, processing order, and an ordered step list.</summary>
public sealed class RuleSet
{
    public ApplyTo ApplyTo { get; set; } = ApplyTo.Name;

    public SortMode Sort { get; set; } = SortMode.Name;

    public List<RuleStep> Steps { get; } = new();

    public RuleSet Clone()
    {
        var copy = new RuleSet { ApplyTo = ApplyTo, Sort = Sort };
        foreach (var step in Steps)
        {
            copy.Steps.Add(step.Clone());
        }

        return copy;
    }
}

