using System.Globalization;
using System.Text;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>Raised when a rules document cannot be understood. The message is user facing.</summary>
public sealed class RulesFormatException : Exception
{
    public RulesFormatException(string message) : base(message)
    {
    }
}

/// <summary>
/// Reader/writer for the <c>rules.json</c> contract. Parsing is explicit rather than
/// reflection based so that every unknown or malformed value produces a precise message
/// instead of being silently defaulted.
/// </summary>
public static class RulesJson
{
    public static RuleSet Parse(string json)
    {
        JsonDocument doc;
        try
        {
            doc = JsonDocument.Parse(json, new JsonDocumentOptions
            {
                AllowTrailingCommas = true,
                CommentHandling = JsonCommentHandling.Skip,
            });
        }
        catch (JsonException ex)
        {
            throw new RulesFormatException($"rules file is not valid JSON: {ex.Message}");
        }

        using (doc)
        {
            var root = doc.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
            {
                throw new RulesFormatException("rules file must contain a JSON object at the root.");
            }

            var set = new RuleSet
            {
                ApplyTo = ParseApplyTo(OptionalString(root, "applyTo") ?? "name"),
                Sort = ParseSort(OptionalString(root, "sort") ?? "name"),
            };

            if (root.TryGetProperty("steps", out var steps))
            {
                if (steps.ValueKind != JsonValueKind.Array)
                {
                    throw new RulesFormatException("\"steps\" must be an array.");
                }

                var i = 0;
                foreach (var element in steps.EnumerateArray())
                {
                    set.Steps.Add(ParseStep(element, i));
                    i++;
                }
            }

            return set;
        }
    }

    public static RuleSet Load(string path) => Parse(File.ReadAllText(path, Encoding.UTF8));

    /// <summary>Serializes a rule set, emitting only the fields that matter for each op.</summary>
    public static string Write(RuleSet set)
    {
        var sb = new StringBuilder();
        sb.Append("{\n");
        sb.Append("  \"applyTo\": ").Append(Json.Quote(Format(set.ApplyTo))).Append(",\n");
        sb.Append("  \"sort\": ").Append(Json.Quote(Format(set.Sort))).Append(",\n");
        sb.Append("  \"steps\": [");

        if (set.Steps.Count == 0)
        {
            sb.Append("]\n}\n");
            return sb.ToString();
        }

        sb.Append('\n');
        for (var i = 0; i < set.Steps.Count; i++)
        {
            sb.Append("    ").Append(WriteStep(set.Steps[i]));
            sb.Append(i == set.Steps.Count - 1 ? "\n" : ",\n");
        }

        sb.Append("  ]\n}\n");
        return sb.ToString();
    }

    public static void Save(string path, RuleSet set)
        => File.WriteAllText(path, Write(set), Json.Utf8NoBom);

    private static string WriteStep(RuleStep step)
    {
        var fields = new List<string> { $"\"op\": {Json.Quote(Format(step.Op))}" };

        switch (step.Op)
        {
            case StepOp.Replace:
                fields.Add($"\"find\": {Json.Quote(step.Find)}");
                fields.Add($"\"replaceWith\": {Json.Quote(step.ReplaceWith)}");
                fields.Add($"\"regex\": {(step.UseRegex ? "true" : "false")}");
                fields.Add($"\"ignoreCase\": {(step.IgnoreCase ? "true" : "false")}");
                break;

            case StepOp.Insert:
                fields.Add($"\"text\": {Json.Quote(step.Text)}");
                fields.Add($"\"position\": {Json.Quote(Format(step.Position))}");
                if (step.Position == Position.Index)
                {
                    fields.Add($"\"index\": {step.Index.ToString(CultureInfo.InvariantCulture)}");
                }

                break;

            case StepOp.Remove:
                fields.Add($"\"from\": {step.From.ToString(CultureInfo.InvariantCulture)}");
                fields.Add($"\"count\": {step.Count.ToString(CultureInfo.InvariantCulture)}");
                break;

            case StepOp.Sequence:
                fields.Add($"\"pattern\": {Json.Quote(step.Pattern)}");
                fields.Add($"\"start\": {step.Start.ToString(CultureInfo.InvariantCulture)}");
                fields.Add($"\"step\": {step.Step.ToString(CultureInfo.InvariantCulture)}");
                fields.Add($"\"position\": {Json.Quote(Format(step.Position))}");
                break;

            case StepOp.Case:
                fields.Add($"\"mode\": {Json.Quote(Format(step.CaseMode))}");
                break;

            case StepOp.Extension:
                fields.Add($"\"mode\": {Json.Quote(Format(step.ExtensionMode))}");
                if (step.ExtensionMode == ExtensionMode.Set)
                {
                    fields.Add($"\"value\": {Json.Quote(step.Value)}");
                }

                break;
        }

        return "{" + string.Join(", ", fields) + "}";
    }

    // ---- parsing helpers -------------------------------------------------

    private static RuleStep ParseStep(JsonElement element, int position)
    {
        if (element.ValueKind != JsonValueKind.Object)
        {
            throw new RulesFormatException($"steps[{position}] must be an object.");
        }

        var opText = OptionalString(element, "op")
                     ?? throw new RulesFormatException($"steps[{position}] is missing \"op\".");

        var step = new RuleStep { Op = ParseOp(opText, position) };

        switch (step.Op)
        {
            case StepOp.Replace:
                step.Find = OptionalString(element, "find") ?? string.Empty;
                step.ReplaceWith = OptionalString(element, "replaceWith") ?? string.Empty;
                step.UseRegex = OptionalBool(element, "regex", position) ?? false;
                step.IgnoreCase = OptionalBool(element, "ignoreCase", position) ?? false;
                break;

            case StepOp.Insert:
                step.Text = OptionalString(element, "text") ?? string.Empty;
                step.Position = ParsePosition(OptionalString(element, "position") ?? "prefix", position, allowIndex: true);
                step.Index = OptionalInt(element, "index", position) ?? 0;
                break;

            case StepOp.Remove:
                step.From = OptionalInt(element, "from", position) ?? 0;
                step.Count = OptionalInt(element, "count", position) ?? 0;
                break;

            case StepOp.Sequence:
                step.Pattern = OptionalString(element, "pattern") ?? "{n:000}";
                step.Start = OptionalInt(element, "start", position) ?? 1;
                step.Step = OptionalInt(element, "step", position) ?? 1;
                step.Position = ParsePosition(OptionalString(element, "position") ?? "prefix", position, allowIndex: false);
                break;

            case StepOp.Case:
                step.CaseMode = ParseCaseMode(
                    OptionalString(element, "mode")
                    ?? throw new RulesFormatException($"steps[{position}] (case) is missing \"mode\"."),
                    position);
                break;

            case StepOp.Extension:
                step.ExtensionMode = ParseExtensionMode(
                    OptionalString(element, "mode")
                    ?? throw new RulesFormatException($"steps[{position}] (extension) is missing \"mode\"."),
                    position);
                step.Value = OptionalString(element, "value") ?? string.Empty;
                break;
        }

        return step;
    }

    private static string? OptionalString(JsonElement parent, string name)
    {
        if (!parent.TryGetProperty(name, out var value) || value.ValueKind == JsonValueKind.Null)
        {
            return null;
        }

        if (value.ValueKind != JsonValueKind.String)
        {
            throw new RulesFormatException($"\"{name}\" must be a string.");
        }

        return value.GetString() ?? string.Empty;
    }

    private static bool? OptionalBool(JsonElement parent, string name, int position)
    {
        if (!parent.TryGetProperty(name, out var value) || value.ValueKind == JsonValueKind.Null)
        {
            return null;
        }

        return value.ValueKind switch
        {
            JsonValueKind.True => true,
            JsonValueKind.False => false,
            _ => throw new RulesFormatException($"steps[{position}].{name} must be true or false."),
        };
    }

    private static int? OptionalInt(JsonElement parent, string name, int position)
    {
        if (!parent.TryGetProperty(name, out var value) || value.ValueKind == JsonValueKind.Null)
        {
            return null;
        }

        if (value.ValueKind != JsonValueKind.Number || !value.TryGetInt32(out var number))
        {
            throw new RulesFormatException($"steps[{position}].{name} must be a 32-bit integer.");
        }

        return number;
    }

    public static ApplyTo ParseApplyTo(string text) => text switch
    {
        "name" => ApplyTo.Name,
        "nameAndExtension" => ApplyTo.NameAndExtension,
        _ => throw new RulesFormatException($"\"applyTo\" must be \"name\" or \"nameAndExtension\" (got \"{text}\")."),
    };

    public static SortMode ParseSort(string text) => text switch
    {
        "name" => SortMode.Name,
        "created" => SortMode.Created,
        "modified" => SortMode.Modified,
        _ => throw new RulesFormatException($"\"sort\" must be \"name\", \"created\" or \"modified\" (got \"{text}\")."),
    };

    private static StepOp ParseOp(string text, int position) => text switch
    {
        "replace" => StepOp.Replace,
        "insert" => StepOp.Insert,
        "remove" => StepOp.Remove,
        "sequence" => StepOp.Sequence,
        "case" => StepOp.Case,
        "extension" => StepOp.Extension,
        _ => throw new RulesFormatException($"steps[{position}] has unknown op \"{text}\"."),
    };

    private static Position ParsePosition(string text, int index, bool allowIndex) => text switch
    {
        "prefix" => Position.Prefix,
        "suffix" => Position.Suffix,
        "index" when allowIndex => Position.Index,
        _ => throw new RulesFormatException(
            $"steps[{index}].position must be {(allowIndex ? "\"prefix\", \"suffix\" or \"index\"" : "\"prefix\" or \"suffix\"")} (got \"{text}\")."),
    };

    private static CaseMode ParseCaseMode(string text, int index) => text switch
    {
        "upper" => CaseMode.Upper,
        "lower" => CaseMode.Lower,
        "title" => CaseMode.Title,
        _ => throw new RulesFormatException($"steps[{index}] (case) mode must be \"upper\", \"lower\" or \"title\" (got \"{text}\")."),
    };

    private static ExtensionMode ParseExtensionMode(string text, int index) => text switch
    {
        "lower" => ExtensionMode.Lower,
        "upper" => ExtensionMode.Upper,
        "set" => ExtensionMode.Set,
        _ => throw new RulesFormatException($"steps[{index}] (extension) mode must be \"lower\", \"upper\" or \"set\" (got \"{text}\")."),
    };

    public static string Format(ApplyTo value) => value == ApplyTo.Name ? "name" : "nameAndExtension";

    public static string Format(SortMode value) => value.ToString().ToLowerInvariant();

    public static string Format(StepOp value) => value.ToString().ToLowerInvariant();

    public static string Format(Position value) => value.ToString().ToLowerInvariant();

    public static string Format(CaseMode value) => value.ToString().ToLowerInvariant();

    public static string Format(ExtensionMode value) => value.ToString().ToLowerInvariant();
}

