        "created" => SortMode.Created,
        "modified" => SortMode.Modified,
        _ => throw new RulesFormatException($"\"sort\" must be \"name\", \"created\" or \"modified\" (got \"{text}\")."),
    };

    private static StepOp ParseOp(string text, int position) => text switch
    {
        "replace" => StepOp.Replace,
        "insert" => StepOp.Insert,
        "remove" => StepOp.Remove,
        "sequence" => StepOp.Sequence,
        "case" => StepOp.Case,
        "extension" => StepOp.Extension,
        _ => throw new RulesFormatException($"steps[{position}] has unknown op \"{text}\"."),
    };

    private static Position ParsePosition(string text, int index, bool allowIndex) => text switch
    {
        "prefix" => Position.Prefix,
        "suffix" => Position.Suffix,
        "index" when allowIndex => Position.Index,
        _ => throw new RulesFormatException(
            $"steps[{index}].position must be {(allowIndex ? "\"prefix\", \"suffix\" or \"index\"" : "\"prefix\" or \"suffix\"")} (got \"{text}\")."),
    };

    private static CaseMode ParseCaseMode(string text, int index) => text switch
    {
        "upper" => CaseMode.Upper,
        "lower" => CaseMode.Lower,
        "title" => CaseMode.Title,
        _ => throw new RulesFormatException($"steps[{index}] (case) mode must be \"upper\", \"lower\" or \"title\" (got \"{text}\")."),
    };

    private static ExtensionMode ParseExtensionMode(string text, int index) => text switch
    {
        "lower" => ExtensionMode.Lower,
        "upper" => ExtensionMode.Upper,
        "set" => ExtensionMode.Set,
        _ => throw new RulesFormatException($"steps[{index}] (extension) mode must be \"lower\", \"upper\" or \"set\" (got \"{text}\")."),
    };

    public static string Format(ApplyTo value) => value == ApplyTo.Name ? "name" : "nameAndExtension";

    public static string Format(SortMode value) => value.ToString().ToLowerInvariant();

    public static string Format(StepOp value) => value.ToString().ToLowerInvariant();

    public static string Format(Position value) => value.ToString().ToLowerInvariant();

    public static string Format(CaseMode value) => value.ToString().ToLowerInvariant();

    public static string Format(ExtensionMode value) => value.ToString().ToLowerInvariant();
}

