namespace BatchRenameStudio.Core;

/// <summary>
/// Minimal JSON emission helpers. Output is written by hand rather than through
/// <c>JsonSerializer</c> so that the byte layout — indentation, line endings, escaping —
/// is fixed by this file and cannot drift with the runtime version. That is what makes
/// plan.json byte-identical for identical inputs (contract rule 15).
/// </summary>
public static class Json
{
    /// <summary>UTF-8 without a byte order mark, as required for plan.json.</summary>
    public static readonly Encoding Utf8NoBom = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false);

    /// <summary>Wraps <paramref name="value"/> in quotes with JSON escaping applied.</summary>
    public static string Quote(string? value)
    {
        var sb = new StringBuilder((value?.Length ?? 0) + 2);
        sb.Append('"');
        Escape(sb, value ?? string.Empty);
        sb.Append('"');
        return sb.ToString();
    }

    private static void Escape(StringBuilder sb, string value)
    {
        for (var i = 0; i < value.Length; i++)
        {
            var c = value[i];
            switch (c)
            {
                case '"':
                    sb.Append("\\\"");
                    continue;
                case '\\':
                    sb.Append("\\\\");
                    continue;
                case '\b':
                    sb.Append("\\b");
                    continue;
                case '\f':
                    sb.Append("\\f");
                    continue;
                case '\n':
                    sb.Append("\\n");
                    continue;
                case '\r':
                    sb.Append("\\r");
                    continue;
                case '\t':
                    sb.Append("\\t");
                    continue;
            }

            if (c < 0x20)
            {
                AppendUnicodeEscape(sb, c);
                continue;
            }

            if (char.IsHighSurrogate(c))
            {
                // Emit a valid pair as-is; escape an unpaired surrogate so the file stays valid UTF-8.
                if (i + 1 < value.Length && char.IsLowSurrogate(value[i + 1]))
                {
                    sb.Append(c).Append(value[i + 1]);
                    i++;
                }
                else
                {
                    AppendUnicodeEscape(sb, c);
                }

                continue;
            }

            if (char.IsLowSurrogate(c))
            {
                AppendUnicodeEscape(sb, c);
                continue;
            }

            sb.Append(c);
        }
    }

    private static void AppendUnicodeEscape(StringBuilder sb, char c)
        => sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
}

