namespace BatchRenameStudio.Core;

/// <summary>
/// The base/extension split defined by contract rule 2. The extension never carries the dot.
/// A leading-dot name such as <c>.gitignore</c> is all base with an empty extension, because
/// the split only happens when the last dot is at index &gt; 0.
/// </summary>
public readonly record struct NameParts(string Base, string Extension)
{
    public static NameParts Split(string fileName)
    {
        var dot = fileName.LastIndexOf('.');
        return dot > 0
            ? new NameParts(fileName[..dot], fileName[(dot + 1)..])
            : new NameParts(fileName, string.Empty);
    }

    /// <summary>Reassembly per contract rule 12: the dot appears only for a non-empty extension.</summary>
    public string Join() => Extension.Length == 0 ? Base : Base + "." + Extension;

    public override string ToString() => Join();
}

