using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>
/// Applies a rule set to one file name. All contract semantics for steps
/// (rules 3, 4, 6-12) live here; nothing about the filesystem does.
/// </summary>
public sealed class RuleEngine
{
    private static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(2);
    private static readonly Regex CounterToken = new(@"\{n:(0+)\}", RegexOptions.CultureInvariant);

    private readonly RuleSet _rules;
    private readonly Regex?[] _compiled;
    private readonly CounterFormat?[] _counters;

    /// <summary>Compiles the rule set. Throws <see cref="RulesFormatException"/> for bad regex or sequence patterns.</summary>
    public RuleEngine(RuleSet rules)
    {
        _rules = rules;
        _compiled = new Regex?[rules.Steps.Count];
        _counters = new CounterFormat?[rules.Steps.Count];

        for (var i = 0; i < rules.Steps.Count; i++)
        {
            var step = rules.Steps[i];

            if (step.Op == StepOp.Replace && step.UseRegex)
            {
                var options = RegexOptions.CultureInvariant;
                if (step.IgnoreCase)
                {
                    options |= RegexOptions.IgnoreCase;
                }

                try
                {
                    _compiled[i] = new Regex(step.Find, options, RegexTimeout);
                }
                catch (ArgumentException ex)
                {
                    throw new RulesFormatException($"steps[{i}] has an invalid regex \"{step.Find}\": {ex.Message}");
                }
            }
            else if (step.Op == StepOp.Sequence)
            {
                _counters[i] = CounterFormat.Parse(step.Pattern, i);
            }
        }
    }

    public ApplyTo ApplyTo => _rules.ApplyTo;

    /// <summary>
    /// Produces the proposed file name for <paramref name="fileName"/>, where
    /// <paramref name="fileIndex"/> is the 0-based position of the file in processing order
    /// (used by sequence counters, which advance for every file regardless of status).
    /// </summary>
    public string Apply(string fileName, int fileIndex)
    {
        if (_rules.ApplyTo == ApplyTo.Name)
        {
            var parts = NameParts.Split(fileName);
            var baseText = parts.Base;
            var extension = parts.Extension;

            for (var i = 0; i < _rules.Steps.Count; i++)
            {
                var step = _rules.Steps[i];
                if (step.Op == StepOp.Extension)
                {
                    extension = ApplyExtension(extension, step);
                }
                else
                {
                    baseText = ApplyToText(baseText, step, i, fileIndex);
                }
            }

            return new NameParts(baseText, extension).Join();
        }

        // nameAndExtension: the target string is the whole name. An extension step still
        // acts on the trailing extension of whatever the string looks like at that moment.
        var whole = fileName;
        for (var i = 0; i < _rules.Steps.Count; i++)
        {
            var step = _rules.Steps[i];
            if (step.Op == StepOp.Extension)
            {
                var parts = NameParts.Split(whole);
                whole = new NameParts(parts.Base, ApplyExtension(parts.Extension, step)).Join();
            }
            else
            {
                whole = ApplyToText(whole, step, i, fileIndex);
            }
        }

        return whole;
    }

    private string ApplyToText(string target, RuleStep step, int stepIndex, int fileIndex) => step.Op switch
    {
        StepOp.Replace => ApplyReplace(target, step, stepIndex),
        StepOp.Insert => ApplyInsert(target, step),
        StepOp.Remove => ApplyRemove(target, step),
        StepOp.Sequence => ApplySequence(target, step, stepIndex, fileIndex),
        StepOp.Case => ApplyCase(target, step.CaseMode),
        _ => target,
    };

    private string ApplyReplace(string target, RuleStep step, int stepIndex)
    {
        if (step.UseRegex)
        {
            var regex = _compiled[stepIndex]!;
            try
            {
                return regex.Replace(target, step.ReplaceWith);
            }
            catch (RegexMatchTimeoutException)
            {
                throw new RulesFormatException(
                    $"steps[{stepIndex}] regex \"{step.Find}\" timed out on \"{target}\"; simplify the pattern.");
            }
        }

        // An empty needle would make string.Replace throw; treat it as a no-op instead.
        if (step.Find.Length == 0)
        {
            return target;
        }

        return target.Replace(
            step.Find,
            step.ReplaceWith,
            step.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);
    }

    private static string ApplyInsert(string target, RuleStep step) => step.Position switch
    {
        Position.Prefix => step.Text + target,
        Position.Suffix => target + step.Text,
        _ => target.Insert(Math.Clamp(step.Index, 0, target.Length), step.Text),
    };

    private static string ApplyRemove(string target, RuleStep step)
    {
        var from = Math.Clamp(step.From, 0, target.Length);
        var count = Math.Clamp(step.Count, 0, target.Length - from);
        return count == 0 ? target : target.Remove(from, count);
    }

    private string ApplySequence(string target, RuleStep step, int stepIndex, int fileIndex)
    {
        // Derived from the file index rather than a mutable counter, so a single engine
        // instance can render any file in any order and still agree with the contract.
        var value = (long)step.Start + ((long)step.Step * fileIndex);
        var rendered = _counters[stepIndex]!.Render(value);
        return step.Position == Position.Suffix ? target + rendered : rendered + target;
    }

    private static string ApplyCase(string target, CaseMode mode)
    {
        switch (mode)
        {
            case CaseMode.Upper:
                return target.ToUpperInvariant();

            case CaseMode.Lower:
                return target.ToLowerInvariant();

            default:
                // Title: first character of each maximal run of letters upper, the rest lower.
                var sb = new StringBuilder(target.Length);
                var inRun = false;
                foreach (var c in target)
                {
                    if (char.IsLetter(c))
                    {
                        sb.Append(inRun ? char.ToLowerInvariant(c) : char.ToUpperInvariant(c));
                        inRun = true;
                    }
                    else
                    {
                        sb.Append(c);
                        inRun = false;
                    }
                }

                return sb.ToString();
        }
    }

    private static string ApplyExtension(string extension, RuleStep step) => step.ExtensionMode switch
    {
        ExtensionMode.Lower => extension.ToLowerInvariant(),
        ExtensionMode.Upper => extension.ToUpperInvariant(),
        _ => step.Value,
    };

    /// <summary>A sequence <c>pattern</c> split around its single <c>{n:000}</c> token.</summary>
    private sealed class CounterFormat
    {
        private readonly string _prefix;
        private readonly string _suffix;
        private readonly string _format;

        private CounterFormat(string prefix, string suffix, int width)
        {
            _prefix = prefix;
            _suffix = suffix;
            _format = new string('0', width);
        }

        public static CounterFormat Parse(string pattern, int stepIndex)
        {
            var matches = CounterToken.Matches(pattern);
            if (matches.Count > 1)
            {
                throw new RulesFormatException(
                    $"steps[{stepIndex}] (sequence) pattern \"{pattern}\" contains {matches.Count} counter tokens; exactly one is allowed.");
            }

            if (matches.Count == 0)
            {
                // No token: the pattern is pure literal text and every file gets the same string.
                return new CounterFormat(pattern, string.Empty, 1);
            }

            var match = matches[0];
            return new CounterFormat(
                pattern[..match.Index],
                pattern[(match.Index + match.Length)..],
                match.Groups[1].Value.Length);
        }

        public string Render(long value)
            => _suffix.Length == 0 && _format.Length == 0
                ? _prefix
                : _prefix + value.ToString(_format, CultureInfo.InvariantCulture) + _suffix;
    }
}

