namespace BatchRenameStudio.Core;

/// <summary>
/// The "is this name usable on Windows" test from contract rule 13. The rule set is fixed
/// by the contract, not probed from the filesystem, so a plan is reproducible anywhere.
/// </summary>
public static class NameValidation
{
    /// <summary>Characters Windows never allows in a file name.</summary>
    public const string ForbiddenCharacters = "<>:\"/\\|?*";

    public const int MaxLength = 255;

    private static readonly HashSet<string> ReservedDeviceNames =
        new(StringComparer.OrdinalIgnoreCase)
        {
            "CON", "PRN", "AUX", "NUL",
            "COM1", "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8", "COM9",
            "LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9",
        };

    /// <summary>
    /// Returns true when <paramref name="name"/> may not be used, with a short
    /// <paramref name="reason"/> suitable for the plan's <c>reason</c> field.
    /// </summary>
    public static bool IsInvalid(string name, out string reason)
    {
        if (name.Length == 0)
        {
            reason = "empty name";
            return true;
        }

        if (name.Length > MaxLength)
        {
            reason = $"name is {name.Length} characters (limit {MaxLength})";
            return true;
        }

        foreach (var c in name)
        {
            if (c < 0x20)
            {
                reason = $"contains control character U+{(int)c:X4}";
                return true;
            }

            if (ForbiddenCharacters.Contains(c))
            {
                reason = $"contains forbidden character '{c}'";
                return true;
            }
        }

        var baseName = NameParts.Split(name).Base;
        if (ReservedDeviceNames.Contains(baseName))
        {
            reason = $"\"{baseName}\" is a reserved device name";
            return true;
        }

        reason = string.Empty;
        return false;
    }
}

