namespace BatchRenameStudio.Core;

/// <summary>Per-item outcome, in the precedence order of contract rule 13.</summary>
public enum PlanStatus
{
    Invalid,
    Collision,
    Unchanged,
    Ok,
}

/// <summary>One file's proposed rename.</summary>
public sealed class PlanItem
{
    public required string Original { get; init; }

    public required string Proposed { get; init; }

    public PlanStatus Status { get; set; }

    public string Reason { get; set; } = string.Empty;

    /// <summary>True when applying this item would actually move a file.</summary>
    public bool IsActionable => Status == PlanStatus.Ok;
}

/// <summary>Counts by status; <see cref="Total"/> is the number of files considered.</summary>
public sealed class PlanSummary
{
    public int Total { get; set; }

    public int Ok { get; set; }

    public int Collision { get; set; }

    public int Unchanged { get; set; }

    public int Invalid { get; set; }
}

/// <summary>The full plan document (schema version 1).</summary>
public sealed class RenamePlan
{
    public const int CurrentSchemaVersion = 1;

    public int SchemaVersion { get; init; } = CurrentSchemaVersion;

    public List<PlanItem> Items { get; } = new();

    public PlanSummary Summary { get; } = new();

    /// <summary>The folder the plan was built from. Not part of the serialized contract.</summary>
    public string Directory { get; init; } = string.Empty;

    public static string Format(PlanStatus status) => status switch
    {
        PlanStatus.Ok => "ok",
        PlanStatus.Collision => "collision",
        PlanStatus.Unchanged => "unchanged",
        _ => "invalid",
    };
}

/// <summary>A folder entry fed to the planner: just the facts the contract can sort on.</summary>
public readonly record struct FileEntry(string Name, DateTime CreatedUtc, DateTime ModifiedUtc);

