/// the filesystem apart from <see cref="ReadFolder"/>: nothing here renames anything.
/// </summary>
public static class PlanBuilder
{
    /// <summary>
    /// Lists the regular files directly inside <paramref name="folder"/> (contract rule 1:
    /// non-recursive, directories excluded).
    /// </summary>
    public static List<FileEntry> ReadFolder(string folder)
    {
        var info = new DirectoryInfo(folder);
        if (!info.Exists)
        {
            throw new DirectoryNotFoundException($"folder not found: {folder}");
        }

        var entries = new List<FileEntry>();
        foreach (var file in info.EnumerateFiles("*", SearchOption.TopDirectoryOnly))
        {
            // EnumerateFiles already excludes directories; the guard covers exotic entries
            // (for example a directory reparse point surfaced as a file entry).
            if ((file.Attributes & FileAttributes.Directory) != 0)
            {
                continue;
            }

            entries.Add(new FileEntry(file.Name, file.CreationTimeUtc, file.LastWriteTimeUtc));
        }

        return entries;
    }

    public static RenamePlan Build(string folder, RuleSet rules)
        => Build(ReadFolder(folder), rules, folder);

    /// <summary>Builds a plan from an explicit file list (used by the GUI preview and by tests).</summary>
    public static RenamePlan Build(IEnumerable<FileEntry> files, RuleSet rules, string folder = "")
    {
        var ordered = Sort(files, rules.Sort);
        var engine = new RuleEngine(rules);
        var plan = new RenamePlan { Directory = folder };

        // Pass 1 — propose a name for every file, in processing order (contract rules 5 and 14).
        for (var i = 0; i < ordered.Count; i++)
        {
            plan.Items.Add(new PlanItem
            {
                Original = ordered[i].Name,
                Proposed = engine.Apply(ordered[i].Name, i),
            });
        }

        // Pass 2 — statuses, which need the whole proposal set to spot collisions.
        var existing = new HashSet<string>(ordered.Select(f => f.Name), StringComparer.OrdinalIgnoreCase);
        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var item in plan.Items)
        {
            proposedCounts[item.Proposed] = proposedCounts.GetValueOrDefault(item.Proposed) + 1;
        }

        foreach (var item in plan.Items)
        {
            if (NameValidation.IsInvalid(item.Proposed, out var reason))
            {
                item.Status = PlanStatus.Invalid;
                item.Reason = reason;
            }
            else if (proposedCounts[item.Proposed] > 1)
            {
                item.Status = PlanStatus.Collision;
                item.Reason = "another file in this plan proposes the same name";
            }
            else if (existing.Contains(item.Proposed) &&
                     !item.Proposed.Equals(item.Original, StringComparison.OrdinalIgnoreCase))
            {
                item.Status = PlanStatus.Collision;
                item.Reason = "a different existing file already uses this name";
            }
            else if (string.Equals(item.Proposed, item.Original, StringComparison.Ordinal))
            {
                item.Status = PlanStatus.Unchanged;
                item.Reason = string.Empty;
            }
            else
            {
                item.Status = PlanStatus.Ok;
                item.Reason = string.Empty;
            }
        }

        plan.Summary.Total = plan.Items.Count;
        plan.Summary.Ok = plan.Items.Count(i => i.Status == PlanStatus.Ok);
        plan.Summary.Collision = plan.Items.Count(i => i.Status == PlanStatus.Collision);
        plan.Summary.Unchanged = plan.Items.Count(i => i.Status == PlanStatus.Unchanged);
        plan.Summary.Invalid = plan.Items.Count(i => i.Status == PlanStatus.Invalid);

        return plan;
    }

    /// <summary>
    /// Processing order (contract rule 5). Timestamp orders fall back to the ordinal name so
    /// that files sharing a timestamp still produce one fixed order (contract rule 15).
    /// </summary>
    public static List<FileEntry> Sort(IEnumerable<FileEntry> files, SortMode mode) => mode switch
    {
        SortMode.Created => files
            .OrderBy(f => f.CreatedUtc)
            .ThenBy(f => f.Name, StringComparer.Ordinal)
            .ToList(),
        SortMode.Modified => files
            .OrderBy(f => f.ModifiedUtc)
            .ThenBy(f => f.Name, StringComparer.Ordinal)
            .ToList(),
        _ => files
            .OrderBy(f => f.Name, StringComparer.Ordinal)
            .ToList(),
    };
}

