using System.Globalization;
using System.Text;

namespace BatchRenameStudio.Core;

/// <summary>
/// Serializes a <see cref="RenamePlan"/> to the plan.json contract: UTF-8 without BOM,
/// LF line endings, two-space indent, one item per line, fixed key order.
/// </summary>
public static class PlanJson
{
    public static string Write(RenamePlan plan)
    {
        var sb = new StringBuilder();
        sb.Append("{\n");
        sb.Append("  \"schemaVersion\": ")
          .Append(plan.SchemaVersion.ToString(CultureInfo.InvariantCulture))
          .Append(",\n");

        if (plan.Items.Count == 0)
        {
            sb.Append("  \"items\": [],\n");
        }
        else
        {
            sb.Append("  \"items\": [\n");
            for (var i = 0; i < plan.Items.Count; i++)
            {
                var item = plan.Items[i];
                sb.Append("    {\"original\": ").Append(Json.Quote(item.Original))
                  .Append(", \"proposed\": ").Append(Json.Quote(item.Proposed))
                  .Append(", \"status\": ").Append(Json.Quote(RenamePlan.Format(item.Status)))
                  .Append(", \"reason\": ").Append(Json.Quote(item.Reason))
                  .Append('}')
                  .Append(i == plan.Items.Count - 1 ? "\n" : ",\n");
            }

            sb.Append("  ],\n");
        }

        var s = plan.Summary;
        sb.Append("  \"summary\": {")
          .Append("\"total\": ").Append(s.Total.ToString(CultureInfo.InvariantCulture))
          .Append(", \"ok\": ").Append(s.Ok.ToString(CultureInfo.InvariantCulture))
          .Append(", \"collision\": ").Append(s.Collision.ToString(CultureInfo.InvariantCulture))
          .Append(", \"unchanged\": ").Append(s.Unchanged.ToString(CultureInfo.InvariantCulture))
          .Append(", \"invalid\": ").Append(s.Invalid.ToString(CultureInfo.InvariantCulture))
          .Append("}\n}\n");

        return sb.ToString();
    }

    /// <summary>Writes the plan to <paramref name="path"/> as UTF-8 with no BOM.</summary>
    public static void Save(string path, RenamePlan plan)
    {
        var directory = Path.GetDirectoryName(Path.GetFullPath(path));
        if (!string.IsNullOrEmpty(directory))
        {
            System.IO.Directory.CreateDirectory(directory);
        }

        File.WriteAllText(path, Write(plan), Json.Utf8NoBom);
    }
}

