using System.Globalization;
using System.Text;

namespace BatchRenameStudio.Core;

/// <summary>A single file move inside one folder, by name.</summary>
public readonly record struct RenameMove(string From, string To);

/// <summary>An applied batch, kept so it can be undone.</summary>
public sealed class RenameOperation
{
    public required string Directory { get; init; }

    public required DateTime TimestampUtc { get; init; }

    public required IReadOnlyList<RenameMove> Moves { get; init; }

    public string Describe()
        => $"{Moves.Count} file(s) in {Directory} at {TimestampUtc.ToLocalTime():yyyy-MM-dd HH:mm:ss}";
}

/// <summary>Outcome of an apply or undo.</summary>
public sealed class RenameResult
{
    public int Succeeded { get; init; }

    public IReadOnlyList<string> Errors { get; init; } = Array.Empty<string>();

    public RenameOperation? Operation { get; init; }

    public bool RolledBack { get; init; }

    public bool IsSuccess => Errors.Count == 0;
}

/// <summary>
/// Performs the renames. Every batch runs in two phases — everything to a temporary name
/// first, then temporary to target — so cycles (a to b, b to a), chains and case-only
/// renames all work without a special case. A failure rolls the batch back.
/// </summary>
public static class RenameExecutor
{
    /// <summary>Applies the <see cref="PlanStatus.Ok"/> items of <paramref name="plan"/>.</summary>
    public static RenameResult Apply(RenamePlan plan, string directory)
    {
        var moves = plan.Items
            .Where(i => i.IsActionable)
            .Select(i => new RenameMove(i.Original, i.Proposed))
            .ToList();

        return Execute(directory, moves);
    }

    /// <summary>Reverses a previously applied operation.</summary>
    public static RenameResult Undo(RenameOperation operation)
    {
        var moves = operation.Moves
            .Select(m => new RenameMove(m.To, m.From))
            .ToList();

        return Execute(operation.Directory, moves);
    }

    public static RenameResult Execute(string directory, IReadOnlyList<RenameMove> moves)
    {
        if (moves.Count == 0)
        {
            return new RenameResult { Succeeded = 0 };
        }

        var token = Guid.NewGuid().ToString("N")[..8];
        var staged = new List<(string TempPath, string TargetPath, RenameMove Move)>(moves.Count);
        var errors = new List<string>();

        // Phase 1 — park every source under a unique temporary name.
        for (var i = 0; i < moves.Count; i++)
        {
            var move = moves[i];
            var sourcePath = Path.Combine(directory, move.From);
            var tempPath = Path.Combine(
                directory,
                string.Create(CultureInfo.InvariantCulture, $"~brs-{token}-{i:D5}.tmp"));

            try
            {
                File.Move(sourcePath, tempPath);
                staged.Add((tempPath, Path.Combine(directory, move.To), move));
            }
            catch (Exception ex)
            {
                errors.Add($"{move.From}: {ex.Message}");
                Rollback(staged);
                return new RenameResult { Succeeded = 0, Errors = errors, RolledBack = true };
            }
        }

        // Phase 2 — move each temporary to its final name.
        var completed = new List<(string TempPath, string TargetPath, RenameMove Move)>(staged.Count);
        foreach (var entry in staged)
        {
            try
            {
                File.Move(entry.TempPath, entry.TargetPath);
                completed.Add(entry);
            }
            catch (Exception ex)
            {
                errors.Add($"{entry.Move.From} -> {entry.Move.To}: {ex.Message}");

                // Put the finished ones back, then unpark the rest.
                foreach (var done in Enumerable.Reverse(completed))
                {
                    TryMove(done.TargetPath, done.TempPath);
                }

                Rollback(staged);
                return new RenameResult { Succeeded = 0, Errors = errors, RolledBack = true };
            }
        }

        var operation = new RenameOperation
        {
            Directory = directory,
            TimestampUtc = DateTime.UtcNow,
            Moves = moves,
        };

        return new RenameResult { Succeeded = moves.Count, Operation = operation };
    }

    private static void Rollback(List<(string TempPath, string TargetPath, RenameMove Move)> staged)
    {
        foreach (var entry in Enumerable.Reverse(staged))
        {
            TryMove(entry.TempPath, Path.Combine(
                Path.GetDirectoryName(entry.TempPath) ?? string.Empty,
                entry.Move.From));
        }
    }

    private static void TryMove(string from, string to)
    {
        try
        {
            if (File.Exists(from))
            {
                File.Move(from, to);
            }
        }
        catch
        {
            // Best effort: a rollback failure is already reported through the primary error.
        }
    }
}

/// <summary>
/// Writes each applied batch to <c>%LOCALAPPDATA%\BatchRenameStudio\history</c> so a rename
/// survives the process that made it. Purely additive: history problems never fail a rename.
/// </summary>
public static class RenameHistory
{
    public static string HistoryDirectory => Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "BatchRenameStudio",
        "history");

    public static string? Record(RenameOperation operation)
    {
        try
        {
            Directory.CreateDirectory(HistoryDirectory);
            var path = Path.Combine(
                HistoryDirectory,
                operation.TimestampUtc.ToString("yyyyMMdd-HHmmss-fff", CultureInfo.InvariantCulture) + ".json");

            var sb = new StringBuilder();
            sb.Append("{\n  \"directory\": ").Append(Json.Quote(operation.Directory)).Append(",\n");
            sb.Append("  \"timestampUtc\": ")
              .Append(Json.Quote(operation.TimestampUtc.ToString("O", CultureInfo.InvariantCulture)))
              .Append(",\n  \"moves\": [\n");
            for (var i = 0; i < operation.Moves.Count; i++)
            {
                sb.Append("    {\"from\": ").Append(Json.Quote(operation.Moves[i].From))
                  .Append(", \"to\": ").Append(Json.Quote(operation.Moves[i].To)).Append('}')
                  .Append(i == operation.Moves.Count - 1 ? "\n" : ",\n");
            }

            sb.Append("  ]\n}\n");
            File.WriteAllText(path, sb.ToString(), Json.Utf8NoBom);
            return path;
        }
        catch
        {
            return null;
        }
    }
}

