using System.Text;

namespace BatchRenameStudio.Cli;

/// <summary>
/// A WinExe has no console of its own. When stdout is redirected (a pipe or a file) the
/// inherited handle already works; when the tool is started from an interactive terminal
/// there is no handle at all, so attach to the parent console and rebuild the writers.
/// Never allocates a new console window.
/// </summary>
internal static class ConsoleBridge
{
    private const int StdOutputHandle = -11;
    private const int StdErrorHandle = -12;
    private const int AttachParentProcess = -1;

    public static void Attach()
    {
        var hasStdout = IsUsable(GetStdHandle(StdOutputHandle));
        var hasStderr = IsUsable(GetStdHandle(StdErrorHandle));
        if (hasStdout && hasStderr)
        {
            return;
        }

        if (!AttachConsole(AttachParentProcess))
        {
            return;
        }

        if (!hasStdout)
        {
            Console.SetOut(NewWriter(Console.OpenStandardOutput()));
        }

        if (!hasStderr)
        {
            Console.SetError(NewWriter(Console.OpenStandardError()));
        }
    }

    private static StreamWriter NewWriter(Stream stream)
        => new(stream, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false)) { AutoFlush = true };

    private static bool IsUsable(IntPtr handle) => handle != IntPtr.Zero && handle != new IntPtr(-1);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(int processId);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetStdHandle(int handle);
}

