using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The headless entry point.
/// <code>BatchRenameStudio.exe --plan --dir &lt;folder&gt; --rules &lt;rules.json&gt; --out &lt;plan.json&gt;</code>
/// Exit codes: 0 success, 2 usage or input error, 3 unexpected failure.
/// In <c>--plan</c> mode stdout carries exactly one summary line and nothing else.
/// </summary>
internal static class CommandLine
{
    public const int ExitSuccess = 0;
    public const int ExitUsage = 2;
    public const int ExitFailure = 3;

    /// <summary>True when the arguments are meant for the console entry point rather than the GUI.</summary>
    public static bool IsCliInvocation(string[] args)
        => args.Any(a => a.StartsWith('-'));

    public static int Run(string[] args)
    {
        try
        {
            if (args.Any(a => a is "--help" or "-h" or "-?" or "/?"))
            {
                Console.Error.WriteLine(UsageText);
                return ExitSuccess;
            }

            if (args.Any(a => a is "--version"))
            {
                Console.Error.WriteLine("Batch Rename Studio 1.0.0");
                return ExitSuccess;
            }

            if (args.Any(a => a is "--selftest"))
            {
                return SelfTest.Run() ? ExitSuccess : ExitFailure;
            }

            if (!args.Any(a => a is "--plan"))
            {
                Console.Error.WriteLine("error: no mode given; expected --plan.");
                Console.Error.WriteLine(UsageText);
                return ExitUsage;
            }

            return RunPlan(args);
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return ExitFailure;
        }
    }

    private static int RunPlan(string[] args)
    {
        string? dir = null, rules = null, output = null;

        for (var i = 0; i < args.Length; i++)
        {
            switch (args[i])
            {
                case "--plan":
                    break;

                case "--dir":
                    if (!TryTakeValue(args, ref i, "--dir", out dir))
                    {
                        return ExitUsage;
                    }

                    break;

                case "--rules":
                    if (!TryTakeValue(args, ref i, "--rules", out rules))
                    {
                        return ExitUsage;
                    }

                    break;

                case "--out":
                    if (!TryTakeValue(args, ref i, "--out", out output))
                    {
                        return ExitUsage;
                    }

                    break;

                default:
                    Console.Error.WriteLine($"error: unknown argument \"{args[i]}\".");
                    Console.Error.WriteLine(UsageText);
                    return ExitUsage;
            }
        }

        if (dir is null || rules is null || output is null)
        {
            Console.Error.WriteLine("error: --plan requires --dir, --rules and --out.");
            Console.Error.WriteLine(UsageText);
            return ExitUsage;
        }

        if (!Directory.Exists(dir))
        {
            Console.Error.WriteLine($"error: folder not found: {dir}");
            return ExitUsage;
        }

        if (!File.Exists(rules))
        {
            Console.Error.WriteLine($"error: rules file not found: {rules}");
            return ExitUsage;
        }

        RuleSet ruleSet;
        try
        {
            ruleSet = RulesJson.Load(rules);
        }
        catch (RulesFormatException ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return ExitUsage;
        }

        RenamePlan plan;
        try
        {
            plan = PlanBuilder.Build(dir, ruleSet);
        }
        catch (RulesFormatException ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return ExitUsage;
        }

        PlanJson.Save(output, plan);

        var s = plan.Summary;
        Console.Out.WriteLine(string.Create(
            CultureInfo.InvariantCulture,
            $"total={s.Total} ok={s.Ok} collision={s.Collision} unchanged={s.Unchanged} invalid={s.Invalid}"));
        Console.Out.Flush();
        return ExitSuccess;
    }

    private static bool TryTakeValue(string[] args, ref int i, string name, out string? value)
    {
        if (i + 1 >= args.Length)
        {
            Console.Error.WriteLine($"error: {name} requires a value.");
            value = null;
            return false;
        }

        value = args[++i];
        return true;
    }

    private const string UsageText = """
        Batch Rename Studio

          BatchRenameStudio.exe
              Launch the graphical rule editor.

          BatchRenameStudio.exe <folder>
              Launch the editor with <folder> already loaded.

          BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>
              Write the rename plan for <folder> and exit. Renames nothing.
              stdout receives one summary line: total=N ok=N collision=N unchanged=N invalid=N

          BatchRenameStudio.exe --selftest
              Run the built-in semantics checks.

        Exit codes: 0 success, 2 usage or input error, 3 unexpected failure.
        """;
}

