using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Built-in checks over the contract semantics, runnable as
/// <c>BatchRenameStudio.exe --selftest</c>. They exercise the pure planning layer only,
/// so they touch no files and are safe to run anywhere.
/// </summary>
internal static class SelfTest
{
    private static int _passed;
    private static readonly List<string> Failures = new();

    public static bool Run()
    {
        _passed = 0;
        Failures.Clear();

        NameSplitting();
        StepSemantics();
        SequenceCounter();
        ApplyToModes();
        StatusPrecedence();
        SortOrder();
        Serialization();

        Console.Out.WriteLine($"selftest: {_passed} passed, {Failures.Count} failed");
        foreach (var failure in Failures)
        {
            Console.Out.WriteLine("  FAIL " + failure);
        }

        return Failures.Count == 0;
    }

    // ---- cases -----------------------------------------------------------

    private static void NameSplitting()
    {
        Split("a.txt", "a", "txt");
        Split(".gitignore", ".gitignore", "");
        Split("readme", "readme", "");
        Split("archive.tar.gz", "archive.tar", "gz");
        Split("trailing.", "trailing", "");
        Split(".", ".", "");

        Eq("join with extension", new NameParts("a", "txt").Join(), "a.txt");
        Eq("join without extension", new NameParts("a", "").Join(), "a");
    }

    private static void StepSemantics()
    {
        Eq("replace all literal",
            Apply("a-b-b.txt", ApplyTo.Name, Replace("b", "X", false, false)), "a-X-X.txt");
        Eq("replace ignore case literal",
            Apply("aBcB.txt", ApplyTo.Name, Replace("b", "-", false, true)), "a-c-.txt");
        Eq("replace regex group",
            Apply("img_12.png", ApplyTo.Name, Replace(@"^img_(\d+)$", "photo-$1", true, false)), "photo-12.png");
        Eq("replace regex ignore case",
            Apply("IMG_9.png", ApplyTo.Name, Replace(@"img_", "shot-", true, true)), "shot-9.png");
        Eq("replace empty needle is a no-op",
            Apply("a.txt", ApplyTo.Name, Replace("", "X", false, false)), "a.txt");

        Eq("insert prefix", Apply("a.txt", ApplyTo.Name, Insert("pre-", Position.Prefix, 0)), "pre-a.txt");
        Eq("insert suffix", Apply("a.txt", ApplyTo.Name, Insert("-end", Position.Suffix, 0)), "a-end.txt");
        Eq("insert at index", Apply("abcd.txt", ApplyTo.Name, Insert("_", Position.Index, 2)), "ab_cd.txt");
        Eq("insert index clamped high", Apply("ab.txt", ApplyTo.Name, Insert("!", Position.Index, 99)), "ab!.txt");
        Eq("insert index clamped low", Apply("ab.txt", ApplyTo.Name, Insert("!", Position.Index, -5)), "!ab.txt");

        Eq("remove range", Apply("abcdef.txt", ApplyTo.Name, Remove(1, 3)), "aef.txt");
        Eq("remove count clamped", Apply("abc.txt", ApplyTo.Name, Remove(1, 99)), "a.txt");
        Eq("remove from clamped", Apply("abc.txt", ApplyTo.Name, Remove(99, 2)), "abc.txt");
        Eq("remove negative from", Apply("abc.txt", ApplyTo.Name, Remove(-3, 2)), "c.txt");

        Eq("case upper", Apply("hello world.txt", ApplyTo.Name, Case(CaseMode.Upper)), "HELLO WORLD.txt");
        Eq("case lower", Apply("HeLLo.TXT", ApplyTo.Name, Case(CaseMode.Lower)), "hello.TXT");
        Eq("case title", Apply("hello-wide WORLD_x9y.txt", ApplyTo.Name, Case(CaseMode.Title)),
            "Hello-Wide World_X9Y.txt");
        Eq("case title keeps non-letters", Apply("a1b2c.txt", ApplyTo.Name, Case(CaseMode.Title)), "A1B2C.txt");

        Eq("extension lower", Apply("a.TXT", ApplyTo.Name, Ext(ExtensionMode.Lower, "")), "a.txt");
        Eq("extension upper", Apply("a.txt", ApplyTo.Name, Ext(ExtensionMode.Upper, "")), "a.TXT");
        Eq("extension set", Apply("a.txt", ApplyTo.Name, Ext(ExtensionMode.Set, "md")), "a.md");
        Eq("extension set gains one", Apply("readme", ApplyTo.Name, Ext(ExtensionMode.Set, "txt")), "readme.txt");
        Eq("extension ignores dotfile split", Apply(".gitignore", ApplyTo.Name, Ext(ExtensionMode.Upper, "")), ".gitignore");

        Eq("steps run in order",
            Apply("ab.txt", ApplyTo.Name, Insert("x", Position.Prefix, 0), Case(CaseMode.Upper)), "XAB.txt");
    }

    private static void SequenceCounter()
    {
        var rules = NewRules(ApplyTo.Name, SortMode.Name, Sequence("{n:000}_", 1, 1, Position.Prefix));
        var plan = PlanBuilder.Build(Entries("b.txt", "a.txt", "c.txt"), rules);

        Eq("sequence follows processing order", plan.Items[0].Proposed, "001_a.txt");
        Eq("sequence second", plan.Items[1].Proposed, "002_b.txt");
        Eq("sequence third", plan.Items[2].Proposed, "003_c.txt");

        var stepped = PlanBuilder.Build(
            Entries("a.txt", "b.txt"),
            NewRules(ApplyTo.Name, SortMode.Name, Sequence("p{n:00}", 10, 5, Position.Suffix)));
        Eq("sequence start/step/suffix", stepped.Items[0].Proposed, "ap10.txt");
        Eq("sequence step applied", stepped.Items[1].Proposed, "bp15.txt");

        // The counter advances for every file, even one that ends up invalid or unchanged.
        var advancing = PlanBuilder.Build(
            Entries("a.txt", "b.txt", "c.txt"),
            NewRules(ApplyTo.Name, SortMode.Name,
                Replace("b", "b?", false, false),
                Sequence("{n:0}-", 1, 1, Position.Prefix)));
        Eq("counter advances past an invalid item", advancing.Items[2].Proposed, "3-c.txt");
        Eq("invalid item keeps its counter", advancing.Items[1].Proposed, "2-b?.txt");

        var wide = NewRules(ApplyTo.Name, SortMode.Name, Sequence("{n:00}", 999, 1, Position.Prefix));
        Eq("pad does not truncate", PlanBuilder.Build(Entries("a.txt"), wide).Items[0].Proposed, "999a.txt");

        var literal = NewRules(ApplyTo.Name, SortMode.Name, Sequence("fixed_", 1, 1, Position.Prefix));
        Eq("pattern without a token is literal",
            PlanBuilder.Build(Entries("a.txt"), literal).Items[0].Proposed, "fixed_a.txt");
    }

    private static void ApplyToModes()
    {
        Eq("name mode leaves the extension alone",
            Apply("photo.JPG", ApplyTo.Name, Case(CaseMode.Lower)), "photo.JPG");
        Eq("nameAndExtension mode covers the extension",
            Apply("photo.JPG", ApplyTo.NameAndExtension, Case(CaseMode.Lower)), "photo.jpg");
        Eq("nameAndExtension replace can hit the dot",
            Apply("a.txt", ApplyTo.NameAndExtension, Replace(".", "_", false, false)), "a_txt");
        Eq("extension step still works in nameAndExtension",
            Apply("photo.JPG", ApplyTo.NameAndExtension, Case(CaseMode.Upper), Ext(ExtensionMode.Lower, "")),
            "PHOTO.jpg");
        Eq("extension set in nameAndExtension",
            Apply("note", ApplyTo.NameAndExtension, Insert("my-", Position.Prefix, 0), Ext(ExtensionMode.Set, "md")),
            "my-note.md");
        Eq("extension step sees the string as it stands",
            Apply("a.txt", ApplyTo.NameAndExtension, Insert(".bak", Position.Suffix, 0), Ext(ExtensionMode.Upper, "")),
            "a.txt.BAK");
    }

    private static void StatusPrecedence()
    {
        var invalid = PlanBuilder.Build(
            Entries("a.txt"),
            NewRules(ApplyTo.Name, SortMode.Name, Insert(":", Position.Prefix, 0)));
        Eq("forbidden character is invalid", Status(invalid, 0), "invalid");

        var reserved = PlanBuilder.Build(
            Entries("a.txt"),
            NewRules(ApplyTo.Name, SortMode.Name, Replace("a", "con", false, false)));
        Eq("reserved device name is invalid", Status(reserved, 0), "invalid");

        var reservedCase = PlanBuilder.Build(
            Entries("a.txt"),
            NewRules(ApplyTo.Name, SortMode.Name, Replace("a", "LpT9", false, false)));
        Eq("reserved name match is case-insensitive", Status(reservedCase, 0), "invalid");

        var tooLong = PlanBuilder.Build(
            Entries("a.txt"),
            NewRules(ApplyTo.Name, SortMode.Name, Insert(new string('x', 260), Position.Prefix, 0)));
        Eq("over 255 characters is invalid", Status(tooLong, 0), "invalid");

        var emptied = PlanBuilder.Build(
            Entries("abc"),
            NewRules(ApplyTo.NameAndExtension, SortMode.Name, Remove(0, 99)));
        Eq("empty name is invalid", Status(emptied, 0), "invalid");

        var pairCollision = PlanBuilder.Build(
            Entries("a.txt", "b.txt"),
            NewRules(ApplyTo.Name, SortMode.Name, Replace("a", "z", false, false), Replace("b", "z", false, false)));
        Eq("two items proposing one name collide (first)", Status(pairCollision, 0), "collision");
        Eq("two items proposing one name collide (second)", Status(pairCollision, 1), "collision");

        var existingCollision = PlanBuilder.Build(
            Entries("a.txt", "B.TXT"),
            NewRules(ApplyTo.Name, SortMode.Name, Replace("a", "b", false, false)));
        Eq("collides with an existing file case-insensitively", Status(existingCollision, 0), "collision");

        var unchanged = PlanBuilder.Build(
            Entries("a.txt"),
            NewRules(ApplyTo.Name, SortMode.Name, Replace("zzz", "y", false, false)));
        Eq("identical name is unchanged", Status(unchanged, 0), "unchanged");

        var caseOnly = PlanBuilder.Build(
            Entries("A.txt"),
            NewRules(ApplyTo.Name, SortMode.Name, Case(CaseMode.Lower)));
        Eq("case-only rename is ok, not a collision", Status(caseOnly, 0), "ok");

        var ok = PlanBuilder.Build(
            Entries("a.txt"),
            NewRules(ApplyTo.Name, SortMode.Name, Insert("new-", Position.Prefix, 0)));
        Eq("plain rename is ok", Status(ok, 0), "ok");

        var summary = PlanBuilder.Build(
            Entries("a.txt", "b.txt", "c.txt"),
            NewRules(ApplyTo.Name, SortMode.Name, Replace("a", "b", false, false)));
        Eq("summary total", summary.Summary.Total.ToString(), "3");
        Eq("summary collision", summary.Summary.Collision.ToString(), "1");
        Eq("summary unchanged", summary.Summary.Unchanged.ToString(), "2");
    }

    private static void SortOrder()
    {
        var plan = PlanBuilder.Build(
            Entries("b.txt", "A.txt", "a.txt", "B.txt"),
            NewRules(ApplyTo.Name, SortMode.Name));
        Eq("ordinal sort is case sensitive",
            string.Join(",", plan.Items.Select(i => i.Original)), "A.txt,B.txt,a.txt,b.txt");

        var byTime = PlanBuilder.Build(
            new[]
            {
                new FileEntry("late.txt", new DateTime(2024, 1, 3), new DateTime(2024, 1, 1)),
                new FileEntry("early.txt", new DateTime(2024, 1, 1), new DateTime(2024, 1, 3)),
            },
            NewRules(ApplyTo.Name, SortMode.Created));
        Eq("created sort ascending",
            string.Join(",", byTime.Items.Select(i => i.Original)), "early.txt,late.txt");

        var byModified = PlanBuilder.Build(
            new[]
            {
                new FileEntry("late.txt", new DateTime(2024, 1, 3), new DateTime(2024, 1, 1)),
                new FileEntry("early.txt", new DateTime(2024, 1, 1), new DateTime(2024, 1, 3)),
            },
            NewRules(ApplyTo.Name, SortMode.Modified));
        Eq("modified sort ascending",
            string.Join(",", byModified.Items.Select(i => i.Original)), "late.txt,early.txt");
    }

    private static void Serialization()
    {
        var plan = PlanBuilder.Build(
            Entries("a.txt"),
            NewRules(ApplyTo.Name, SortMode.Name, Sequence("{n:000}_", 1, 1, Position.Prefix)));
        var text = PlanJson.Write(plan);

        True("plan.json uses LF only", !text.Contains('\r'));
        True("plan.json declares the schema version", text.Contains("\"schemaVersion\": 1"));
        True("plan.json carries the item", text.Contains("\"proposed\": \"001_a.txt\""));
        True("plan.json carries the summary", text.Contains("\"summary\": {\"total\": 1"));

        var bytes = Json.Utf8NoBom.GetBytes(text);
        True("plan.json has no BOM", bytes.Length < 3 || !(bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF));

        Eq("plan.json is deterministic", PlanJson.Write(plan), text);

        Eq("json escaping", Json.Quote("a\"b\\c\td"), "\"a\\\"b\\\\c\\td\"");
        Eq("json keeps non-ascii raw", Json.Quote("檔案"), "\"檔案\"");

        var roundTrip = RulesJson.Parse(RulesJson.Write(NewRules(
            ApplyTo.NameAndExtension,
            SortMode.Modified,
            Replace("a", "b", true, true),
            Insert("x", Position.Index, 3),
            Remove(1, 2),
            Sequence("{n:0000}", 5, 2, Position.Suffix),
            Case(CaseMode.Title),
            Ext(ExtensionMode.Set, "md"))));

        Eq("rules round-trip applyTo", RulesJson.Format(roundTrip.ApplyTo), "nameAndExtension");
        Eq("rules round-trip sort", RulesJson.Format(roundTrip.Sort), "modified");
        Eq("rules round-trip step count", roundTrip.Steps.Count.ToString(), "6");
        Eq("rules round-trip regex flag", roundTrip.Steps[0].UseRegex.ToString(), "True");
        Eq("rules round-trip index", roundTrip.Steps[1].Index.ToString(), "3");
        Eq("rules round-trip sequence step", roundTrip.Steps[3].Step.ToString(), "2");
        Eq("rules round-trip case mode", RulesJson.Format(roundTrip.Steps[4].CaseMode), "title");
        Eq("rules round-trip extension value", roundTrip.Steps[5].Value, "md");

        Throws("unknown op is rejected", () => RulesJson.Parse("""{"steps":[{"op":"nope"}]}"""));
        Throws("unknown applyTo is rejected", () => RulesJson.Parse("""{"applyTo":"both"}"""));
        Throws("bad regex is rejected", () => new RuleEngine(NewRules(
            ApplyTo.Name, SortMode.Name, Replace("([", "x", true, false))));
        Throws("two counter tokens are rejected", () => new RuleEngine(NewRules(
            ApplyTo.Name, SortMode.Name, Sequence("{n:0}{n:00}", 1, 1, Position.Prefix))));
    }

    // ---- helpers ---------------------------------------------------------

    private static void Split(string name, string expectedBase, string expectedExt)
    {
        var parts = NameParts.Split(name);
        Eq($"split \"{name}\" base", parts.Base, expectedBase);
        Eq($"split \"{name}\" ext", parts.Extension, expectedExt);
    }

    private static string Status(RenamePlan plan, int index) => RenamePlan.Format(plan.Items[index].Status);

    private static string Apply(string fileName, ApplyTo applyTo, params RuleStep[] steps)
        => new RuleEngine(NewRules(applyTo, SortMode.Name, steps)).Apply(fileName, 0);

    private static RuleSet NewRules(ApplyTo applyTo, SortMode sort, params RuleStep[] steps)
    {
        var set = new RuleSet { ApplyTo = applyTo, Sort = sort };
        set.Steps.AddRange(steps);
        return set;
    }

    private static IEnumerable<FileEntry> Entries(params string[] names)
        => names.Select((n, i) => new FileEntry(n, new DateTime(2024, 1, 1).AddMinutes(i), new DateTime(2024, 1, 1).AddMinutes(i)));

    private static RuleStep Replace(string find, string with, bool regex, bool ignoreCase)
        => new() { Op = StepOp.Replace, Find = find, ReplaceWith = with, UseRegex = regex, IgnoreCase = ignoreCase };

    private static RuleStep Insert(string text, Position position, int index)
        => new() { Op = StepOp.Insert, Text = text, Position = position, Index = index };

    private static RuleStep Remove(int from, int count)
        => new() { Op = StepOp.Remove, From = from, Count = count };

    private static RuleStep Sequence(string pattern, int start, int step, Position position)
        => new() { Op = StepOp.Sequence, Pattern = pattern, Start = start, Step = step, Position = position };

    private static RuleStep Case(CaseMode mode) => new() { Op = StepOp.Case, CaseMode = mode };

    private static RuleStep Ext(ExtensionMode mode, string value)
        => new() { Op = StepOp.Extension, ExtensionMode = mode, Value = value };

    private static void Eq(string label, string actual, string expected)
    {
        if (string.Equals(actual, expected, StringComparison.Ordinal))
