using BatchRenameStudio.Cli;
using BatchRenameStudio.Ui;

namespace BatchRenameStudio;

internal static class Program
{
    /// <summary>
    /// One executable, two faces: any argument starting with '-' selects the headless
    /// command line, anything else launches the editor (an existing folder path preloads it).
    /// </summary>
    [STAThread]
    private static int Main(string[] args)
    {
        if (args.Length > 0 && CommandLine.IsCliInvocation(args))
        {
            ConsoleBridge.Attach();
            return CommandLine.Run(args);
        }

        var initialFolder = args.Length > 0 && Directory.Exists(args[0]) ? args[0] : null;

        ApplicationConfiguration.Initialize();
        Application.Run(new MainForm(initialFolder));
        return 0;
    }
}

