using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// Editor for one <see cref="RuleStep"/>. The control instances are created once and the
/// layout is rebuilt from a cached set when the op changes, so event wiring stays fixed and
/// only the rows that matter for the current op are visible.
/// </summary>
internal sealed class StepEditorPanel : UserControl
{
    private readonly TableLayoutPanel _grid;
    private readonly ComboBox _op = new();
    private readonly TextBox _find = new();
    private readonly TextBox _replaceWith = new();
    private readonly CheckBox _regex = new() { Text = "Regular expression ($1 back-references allowed)" };
    private readonly CheckBox _ignoreCase = new() { Text = "Ignore case" };
    private readonly TextBox _text = new();
    private readonly ComboBox _position = new();
    private readonly NumericUpDown _index = new();
    private readonly NumericUpDown _from = new();
    private readonly NumericUpDown _count = new();
    private readonly TextBox _pattern = new();
    private readonly NumericUpDown _start = new();
    private readonly NumericUpDown _step = new();
    private readonly ComboBox _caseMode = new();
    private readonly ComboBox _extensionMode = new();
    private readonly TextBox _value = new();
    private readonly Label _hint = new();

    private RuleStep? _step2;
    private bool _loading;

    public StepEditorPanel()
    {
        Dock = DockStyle.Fill;
        Padding = new Padding(8);

        _grid = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 2,
            AutoScroll = true,
            GrowStyle = TableLayoutPanelGrowStyle.AddRows,
        };
        _grid.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 120));
        _grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        Controls.Add(_grid);

        ConfigureCombo(_op, "replace", "insert", "remove", "sequence", "case", "extension");
        ConfigureCombo(_caseMode, "upper", "lower", "title");
        ConfigureCombo(_extensionMode, "lower", "upper", "set");

        foreach (var numeric in new[] { _index, _from, _count })
        {
            numeric.Minimum = -100000;
            numeric.Maximum = 100000;
            numeric.Width = 100;
        }

        foreach (var numeric in new[] { _start, _step })
        {
            numeric.Minimum = -1000000;
            numeric.Maximum = 1000000;
            numeric.Width = 100;
        }

        _hint.AutoSize = false;
        _hint.Height = 34;
        _hint.ForeColor = SystemColors.GrayText;
        _hint.Dock = DockStyle.Fill;

        _op.SelectedIndexChanged += (_, _) => OnOpChanged();
        foreach (var box in new[] { _find, _replaceWith, _text, _pattern, _value })
        {
            box.TextChanged += (_, _) => Commit();
        }

        foreach (var check in new[] { _regex, _ignoreCase })
        {
            check.AutoSize = true;
            check.CheckedChanged += (_, _) => Commit();
        }

        foreach (var numeric in new[] { _index, _from, _count, _start, _step })
        {
            numeric.ValueChanged += (_, _) => Commit();
        }

        foreach (var combo in new[] { _position, _caseMode, _extensionMode })
        {
            combo.SelectedIndexChanged += (_, _) => Commit();
        }
    }

    /// <summary>Raised whenever the edited step changed and the preview should be rebuilt.</summary>
    public event EventHandler? StepChanged;

    /// <summary>Points the editor at <paramref name="step"/>, or disables it when null.</summary>
    public void Bind(RuleStep? step)
    {
        _step2 = step;
        Enabled = step is not null;
        if (step is null)
        {
            _grid.Controls.Clear();
            return;
        }

        _loading = true;
        _op.SelectedItem = RulesJson.Format(step.Op);
        _find.Text = step.Find;
        _replaceWith.Text = step.ReplaceWith;
        _regex.Checked = step.UseRegex;
        _ignoreCase.Checked = step.IgnoreCase;
        _text.Text = step.Text;
        _index.Value = Clamp(_index, step.Index);
        _from.Value = Clamp(_from, step.From);
        _count.Value = Clamp(_count, step.Count);
        _pattern.Text = step.Pattern;
        _start.Value = Clamp(_start, step.Start);
        _step.Value = Clamp(_step, step.Step);
        _caseMode.SelectedItem = RulesJson.Format(step.CaseMode);
        _extensionMode.SelectedItem = RulesJson.Format(step.ExtensionMode);
        BuildRows(step);
        _loading = false;
    }

    private void OnOpChanged()
    {
        if (_loading || _step2 is null)
        {
            return;
        }

        _step2.Op = (string)_op.SelectedItem! switch
        {
            "insert" => StepOp.Insert,
            "remove" => StepOp.Remove,
            "sequence" => StepOp.Sequence,
            "case" => StepOp.Case,
            "extension" => StepOp.Extension,
            _ => StepOp.Replace,
        };

        _loading = true;
        BuildRows(_step2);
        _loading = false;
        StepChanged?.Invoke(this, EventArgs.Empty);
    }

    private void Commit()
    {
        if (_loading || _step2 is null)
        {
            return;
        }

        var step = _step2;
        step.Find = _find.Text;
        step.ReplaceWith = _replaceWith.Text;
        step.UseRegex = _regex.Checked;
        step.IgnoreCase = _ignoreCase.Checked;
        step.Text = _text.Text;
        step.Index = (int)_index.Value;
        step.From = (int)_from.Value;
        step.Count = (int)_count.Value;
        step.Pattern = _pattern.Text;
        step.Start = (int)_start.Value;
        step.Step = (int)_step.Value;
        step.Value = _value.Text;

        if (_position.SelectedItem is string position)
        {
            step.Position = position switch
            {
                "suffix" => Position.Suffix,
                "index" => Position.Index,
                _ => Position.Prefix,
            };
        }

        if (_caseMode.SelectedItem is string caseMode)
        {
            step.CaseMode = caseMode switch
            {
                "upper" => CaseMode.Upper,
                "title" => CaseMode.Title,
                _ => CaseMode.Lower,
            };
        }

        if (_extensionMode.SelectedItem is string extensionMode)
        {
            step.ExtensionMode = extensionMode switch
            {
                "upper" => ExtensionMode.Upper,
                "set" => ExtensionMode.Set,
                _ => ExtensionMode.Lower,
            };
        }

        // Positional rows appear and disappear with the selection (insert index, set value).
        if (step.Op is StepOp.Insert or StepOp.Extension)
        {
            var wasLoading = _loading;
            _loading = true;
            BuildRows(step);
            _loading = wasLoading;
        }

        StepChanged?.Invoke(this, EventArgs.Empty);
    }

    private void BuildRows(RuleStep step)
    {
        _grid.SuspendLayout();
        _grid.Controls.Clear();
        _grid.RowStyles.Clear();
        _grid.RowCount = 0;

        AddRow("Operation", _op);

        switch (step.Op)
        {
            case StepOp.Replace:
                AddRow("Find", _find);
                AddRow("Replace with", _replaceWith);
                AddRow(string.Empty, _regex);
                AddRow(string.Empty, _ignoreCase);
                SetHint("Replaces every occurrence. With regex on, $1 refers to the first capture group.");
                break;

            case StepOp.Insert:
                AddRow("Text", _text);
                ConfigureCombo(_position, "prefix", "suffix", "index");
                SelectPosition(step.Position);
                AddRow("Position", _position);
                if (step.Position == Position.Index)
                {
                    AddRow("Index", _index);
                }

                SetHint("Index is 0-based and clamped to the length of the target string.");
                break;

            case StepOp.Remove:
                AddRow("From index", _from);
                AddRow("Count", _count);
                SetHint("Removes Count characters starting at From. Both are clamped to what exists.");
                break;

            case StepOp.Sequence:
                AddRow("Pattern", _pattern);
                AddRow("Start", _start);
                AddRow("Step", _step);
                ConfigureCombo(_position, "prefix", "suffix");
                SelectPosition(step.Position == Position.Suffix ? Position.Suffix : Position.Prefix);
                AddRow("Position", _position);
                SetHint("Pattern holds literal text plus one {n:000} token; the zeros set the padding width. "
                        + "The counter advances for every file in the folder.");
                break;

            case StepOp.Case:
                AddRow("Mode", _caseMode);
                SetHint("Title uppercases the first letter of each run of letters and lowercases the rest.");
                break;

            case StepOp.Extension:
                AddRow("Mode", _extensionMode);
                if (step.ExtensionMode == ExtensionMode.Set)
                {
                    _value.Text = step.Value;
                    AddRow("Value", _value);
                }

                SetHint("Extension steps always act on the extension, whatever the scope setting is. "
                        + "Write the value without a leading dot.");
                break;
        }

        AddRow(string.Empty, _hint);
        _grid.ResumeLayout();
    }

    private void SelectPosition(Position position)
    {
        var text = RulesJson.Format(position);
        _position.SelectedItem = _position.Items.Contains(text) ? text : "prefix";
    }

    private void AddRow(string label, Control control)
    {
        _grid.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        _grid.Controls.Add(
            new Label
            {
                Text = label,
                TextAlign = ContentAlignment.MiddleLeft,
                Dock = DockStyle.Fill,
                Margin = new Padding(0, 6, 6, 0),
                AutoSize = false,
                Height = 24,
            },
            0,
            _grid.RowCount);

        control.Margin = new Padding(0, 3, 0, 3);
        if (control is TextBox or ComboBox)
        {
            control.Dock = DockStyle.Fill;
        }

        _grid.Controls.Add(control, 1, _grid.RowCount);
        _grid.RowCount++;
    }

    private void SetHint(string text) => _hint.Text = text;

    private static void ConfigureCombo(ComboBox combo, params string[] items)
    {
        var previous = combo.SelectedItem as string;
        combo.DropDownStyle = ComboBoxStyle.DropDownList;
        combo.Items.Clear();
        combo.Items.AddRange(items);
        if (previous is not null && combo.Items.Contains(previous))
        {
            combo.SelectedItem = previous;
        }
        else if (combo.Items.Count > 0)
        {
            combo.SelectedIndex = 0;
        }
    }

    private static decimal Clamp(NumericUpDown control, int value)
        => Math.Clamp(value, (int)control.Minimum, (int)control.Maximum);
}

