using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// The editor window: pick a folder, stack up steps, watch the preview, apply, undo.
/// The preview is the same <see cref="PlanBuilder"/> output the headless mode writes, so
/// what the window shows and what <c>--plan</c> produces can never drift apart.
/// </summary>
internal sealed class MainForm : Form
{
    private static readonly Color OkBack = Color.FromArgb(233, 246, 236);
    private static readonly Color CollisionBack = Color.FromArgb(255, 243, 221);
    private static readonly Color InvalidBack = Color.FromArgb(255, 233, 235);

    private readonly RuleSet _rules = new();
    private readonly List<FileEntry> _files = new();
    private readonly Stack<RenameOperation> _undoStack = new();

    private readonly TextBox _folderBox = new();
    private readonly ComboBox _applyToBox = new();
    private readonly ComboBox _sortBox = new();
    private readonly ListBox _stepList = new();
    private readonly StepEditorPanel _editor = new();
    private readonly ListView _preview = new();
    private readonly Label _summaryLabel = new();
    private readonly Button _applyButton = new();
    private readonly Button _undoButton = new();
    private readonly ToolStripStatusLabel _statusLabel = new();

    private RenamePlan? _plan;
    private string _folder = string.Empty;
    private bool _suspendSync;

    public MainForm(string? initialFolder)
    {
        Text = "Batch Rename Studio";
        MinimumSize = new Size(980, 620);
        Size = new Size(1180, 760);
        StartPosition = FormStartPosition.CenterScreen;
        Font = new Font("Segoe UI", 9F);

        var split = BuildSplit();
        Controls.Add(split);
        Controls.Add(BuildFolderPanel());
        Controls.Add(BuildStatusStrip());
        Controls.Add(BuildMenu());

        SyncOptionBoxes();
        UpdateStepList(-1);
        SetStatus("Pick a folder to get started.");

        if (!string.IsNullOrEmpty(initialFolder))
        {
            LoadFolder(initialFolder!);
        }
    }

    // ---- construction ----------------------------------------------------

    private MenuStrip BuildMenu()
    {
        var file = new ToolStripMenuItem("&File");
        file.DropDownItems.Add("&Open folder...", null, (_, _) => BrowseForFolder()).ShortcutKeys =
            Keys.Control | Keys.O;
        file.DropDownItems.Add("&Reload folder", null, (_, _) => ReloadFolder()).ShortcutKeys = Keys.F5;
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add("&Load rules...", null, (_, _) => LoadRules());
        file.DropDownItems.Add("&Save rules as...", null, (_, _) => SaveRules());
        file.DropDownItems.Add("&Export plan.json...", null, (_, _) => ExportPlan());
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add("E&xit", null, (_, _) => Close());

        var rules = new ToolStripMenuItem("&Rules");
        var add = new ToolStripMenuItem("&Add step");
        foreach (var op in Enum.GetValues<StepOp>())
        {
            add.DropDownItems.Add(RulesJson.Format(op), null, (_, _) => AddStep(op));
        }

        rules.DropDownItems.Add(add);
        rules.DropDownItems.Add("&Duplicate step", null, (_, _) => DuplicateStep());
        rules.DropDownItems.Add("D&elete step", null, (_, _) => DeleteStep());
        rules.DropDownItems.Add(new ToolStripSeparator());
        rules.DropDownItems.Add("Move &up", null, (_, _) => MoveStep(-1));
        rules.DropDownItems.Add("Move &down", null, (_, _) => MoveStep(1));
        rules.DropDownItems.Add(new ToolStripSeparator());
        rules.DropDownItems.Add("&Clear all steps", null, (_, _) => ClearSteps());

        var help = new ToolStripMenuItem("&Help");
        help.DropDownItems.Add("Run &self-test", null, (_, _) => RunSelfTest());
        help.DropDownItems.Add("&About", null, (_, _) => ShowAbout());

        var menu = new MenuStrip();
        menu.Items.AddRange(new ToolStripItem[] { file, rules, help });
        MainMenuStrip = menu;
        return menu;
    }

    private Panel BuildFolderPanel()
    {
        _folderBox.Dock = DockStyle.Fill;
        _folderBox.PlaceholderText = @"C:\path\to\folder";
        _folderBox.KeyDown += (_, e) =>
        {
            if (e.KeyCode == Keys.Enter)
            {
                e.SuppressKeyPress = true;
                LoadFolder(_folderBox.Text.Trim());
            }
        };

        var browse = MakeButton("Browse...", BrowseForFolder, 90);
        var reload = MakeButton("Reload", ReloadFolder, 80);

        var options = new FlowLayoutPanel { Dock = DockStyle.Fill, AutoSize = true, WrapContents = false };
        options.Controls.Add(MakeLabel("Apply steps to:", 92));
        _applyToBox.DropDownStyle = ComboBoxStyle.DropDownList;
        _applyToBox.Items.AddRange(new object[] { "name", "nameAndExtension" });
        _applyToBox.Width = 150;
        _applyToBox.SelectedIndexChanged += (_, _) => OnOptionsChanged();
        options.Controls.Add(_applyToBox);

        options.Controls.Add(MakeLabel("Process order:", 90));
        _sortBox.DropDownStyle = ComboBoxStyle.DropDownList;
        _sortBox.Items.AddRange(new object[] { "name", "created", "modified" });
        _sortBox.Width = 110;
        _sortBox.SelectedIndexChanged += (_, _) => OnOptionsChanged();
        options.Controls.Add(_sortBox);

        var grid = new TableLayoutPanel
        {
            Dock = DockStyle.Top,
            ColumnCount = 4,
            RowCount = 2,
            Height = 76,
            Padding = new Padding(10, 8, 10, 4),
        };
        grid.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 56));
        grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        grid.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        grid.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        grid.RowStyles.Add(new RowStyle(SizeType.Absolute, 32));
        grid.RowStyles.Add(new RowStyle(SizeType.Absolute, 32));
        grid.Controls.Add(MakeLabel("Folder:", 50), 0, 0);
        grid.Controls.Add(_folderBox, 1, 0);
        grid.Controls.Add(browse, 2, 0);
        grid.Controls.Add(reload, 3, 0);
        grid.Controls.Add(options, 1, 1);

        var host = new Panel { Dock = DockStyle.Top, Height = 76 };
        host.Controls.Add(grid);
        return host;
    }

    private SplitContainer BuildSplit()
    {
        var split = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Vertical,
            SplitterDistance = 470,
            SplitterWidth = 6,
        };

        split.Panel1.Controls.Add(BuildRulesPane());
        split.Panel1MinSize = 360;
        split.Panel2.Controls.Add(BuildPreviewPane());
        split.Panel2MinSize = 380;
        return split;
    }

    private Control BuildRulesPane()
    {
        _stepList.Dock = DockStyle.Fill;
        _stepList.IntegralHeight = false;
        _stepList.SelectedIndexChanged += (_, _) =>
        {
            if (!_suspendSync)
            {
                _editor.Bind(SelectedStep);
            }
        };

        _editor.StepChanged += (_, _) =>
        {
            UpdateStepList(_stepList.SelectedIndex, keepEditor: true);
            RefreshPreview();
        };

        var buttons = new FlowLayoutPanel
        {
            Dock = DockStyle.Fill,
            AutoSize = true,
            WrapContents = false,
            Padding = new Padding(0, 2, 0, 2),
        };

        var addMenu = new ContextMenuStrip();
        foreach (var op in Enum.GetValues<StepOp>())
        {
            addMenu.Items.Add(RulesJson.Format(op), null, (_, _) => AddStep(op));
        }

        var addButton = MakeButton("Add step ▾", () => { }, 96);
        addButton.Click += (_, _) => addMenu.Show(addButton, new Point(0, addButton.Height));
        buttons.Controls.Add(addButton);
        buttons.Controls.Add(MakeButton("Duplicate", DuplicateStep, 80));
        buttons.Controls.Add(MakeButton("Delete", DeleteStep, 68));
        buttons.Controls.Add(MakeButton("Up", () => MoveStep(-1), 46));
        buttons.Controls.Add(MakeButton("Down", () => MoveStep(1), 56));

        var editorBox = new GroupBox { Text = "Step settings", Dock = DockStyle.Fill };
        editorBox.Controls.Add(_editor);

        var grid = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 4,
            Padding = new Padding(10, 6, 6, 8),
        };
        grid.RowStyles.Add(new RowStyle(SizeType.Absolute, 22));
        grid.RowStyles.Add(new RowStyle(SizeType.Absolute, 34));
        grid.RowStyles.Add(new RowStyle(SizeType.Percent, 42));
        grid.RowStyles.Add(new RowStyle(SizeType.Percent, 58));
        grid.Controls.Add(MakeLabel("Steps (applied top to bottom)", 260), 0, 0);
        grid.Controls.Add(buttons, 0, 1);
        grid.Controls.Add(_stepList, 0, 2);
        grid.Controls.Add(editorBox, 0, 3);
        return grid;
    }

    private Control BuildPreviewPane()
    {
        _preview.Dock = DockStyle.Fill;
        _preview.View = View.Details;
        _preview.FullRowSelect = true;
        _preview.GridLines = true;
        _preview.HideSelection = false;
        _preview.MultiSelect = false;
        _preview.Columns.Add("#", 42, HorizontalAlignment.Right);
        _preview.Columns.Add("Original", 220);
        _preview.Columns.Add("Proposed", 240);
        _preview.Columns.Add("Status", 80);
        _preview.Columns.Add("Reason", 220);

        _summaryLabel.Dock = DockStyle.Fill;
        _summaryLabel.TextAlign = ContentAlignment.MiddleLeft;
        _summaryLabel.Text = "No folder loaded.";

        _applyButton.Text = "Apply rename";
        _applyButton.Width = 120;
        _applyButton.Height = 30;
        _applyButton.Enabled = false;
        _applyButton.Click += (_, _) => ApplyRename();

        _undoButton.Text = "Undo last";
        _undoButton.Width = 100;
        _undoButton.Height = 30;
        _undoButton.Enabled = false;
        _undoButton.Click += (_, _) => UndoLast();

        var actions = new FlowLayoutPanel
        {
            Dock = DockStyle.Fill,
            FlowDirection = FlowDirection.RightToLeft,
            WrapContents = false,
        };
        actions.Controls.Add(_applyButton);
        actions.Controls.Add(_undoButton);
        actions.Controls.Add(MakeButton("Export plan...", ExportPlan, 110, 30));

        var bottom = new TableLayoutPanel
        {
            Dock = DockStyle.Bottom,
            Height = 44,
            ColumnCount = 2,
            RowCount = 1,
            Padding = new Padding(0, 6, 0, 0),
        };
        bottom.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        bottom.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 356));
        bottom.Controls.Add(_summaryLabel, 0, 0);
        bottom.Controls.Add(actions, 1, 0);

        var host = new Panel { Dock = DockStyle.Fill, Padding = new Padding(6, 6, 10, 8) };
        host.Controls.Add(_preview);
        host.Controls.Add(bottom);
        return host;
    }

    private StatusStrip BuildStatusStrip()
    {
        var strip = new StatusStrip();
        _statusLabel.Spring = true;
        _statusLabel.TextAlign = ContentAlignment.MiddleLeft;
        strip.Items.Add(_statusLabel);
        return strip;
    }

    // ---- folder ----------------------------------------------------------

    private void BrowseForFolder()
    {
        using var dialog = new FolderBrowserDialog { Description = "Choose the folder to rename in" };
        if (!string.IsNullOrEmpty(_folder) && Directory.Exists(_folder))
        {
            dialog.SelectedPath = _folder;
        }

        if (dialog.ShowDialog(this) == DialogResult.OK)
        {
            LoadFolder(dialog.SelectedPath);
        }
    }

    private void LoadFolder(string folder)
    {
        if (string.IsNullOrWhiteSpace(folder))
        {
            return;
        }

        if (!Directory.Exists(folder))
        {
            SetStatus($"Folder not found: {folder}");
            return;
        }

        _folder = Path.GetFullPath(folder);
        _folderBox.Text = _folder;
        ReloadFolder();
    }

    private void ReloadFolder()
    {
        if (string.IsNullOrEmpty(_folder))
        {
            return;
        }

        _files.Clear();
        try
        {
            _files.AddRange(PlanBuilder.ReadFolder(_folder));
            SetStatus($"{_files.Count} file(s) in {_folder}");
        }
        catch (Exception ex)
        {
            SetStatus($"Could not read the folder: {ex.Message}");
        }

        RefreshPreview();
    }

    // ---- rules -----------------------------------------------------------

    private RuleStep? SelectedStep
        => _stepList.SelectedIndex >= 0 && _stepList.SelectedIndex < _rules.Steps.Count
            ? _rules.Steps[_stepList.SelectedIndex]
            : null;

    private void OnOptionsChanged()
    {
        if (_suspendSync)
        {
            return;
        }

        _rules.ApplyTo = RulesJson.ParseApplyTo((string)_applyToBox.SelectedItem!);
        _rules.Sort = RulesJson.ParseSort((string)_sortBox.SelectedItem!);
        RefreshPreview();
    }

    private void SyncOptionBoxes()
    {
        _suspendSync = true;
        _applyToBox.SelectedItem = RulesJson.Format(_rules.ApplyTo);
        _sortBox.SelectedItem = RulesJson.Format(_rules.Sort);
        _suspendSync = false;
    }

    private void AddStep(StepOp op)
    {
        var step = new RuleStep { Op = op };
        switch (op)
        {
            case StepOp.Sequence:
                step.Pattern = "{n:000}_";
                break;
            case StepOp.Insert:
                step.Text = "new-";
                break;
            case StepOp.Extension:
                step.Value = "txt";
                break;
        }

        var at = _stepList.SelectedIndex >= 0 ? _stepList.SelectedIndex + 1 : _rules.Steps.Count;
        _rules.Steps.Insert(at, step);
        UpdateStepList(at);
        RefreshPreview();
    }

    private void DuplicateStep()
    {
        if (SelectedStep is not { } step)
        {
            return;
        }

        var at = _stepList.SelectedIndex + 1;
        _rules.Steps.Insert(at, step.Clone());
        UpdateStepList(at);
        RefreshPreview();
    }

    private void DeleteStep()
    {
        var index = _stepList.SelectedIndex;
        if (index < 0)
        {
            return;
        }

        _rules.Steps.RemoveAt(index);
        UpdateStepList(Math.Min(index, _rules.Steps.Count - 1));
        RefreshPreview();
    }

    private void MoveStep(int delta)
    {
        var index = _stepList.SelectedIndex;
        var target = index + delta;
        if (index < 0 || target < 0 || target >= _rules.Steps.Count)
        {
            return;
        }

        (_rules.Steps[index], _rules.Steps[target]) = (_rules.Steps[target], _rules.Steps[index]);
        UpdateStepList(target);
        RefreshPreview();
    }

    private void ClearSteps()
    {
        if (_rules.Steps.Count == 0)
        {
            return;
        }

        _rules.Steps.Clear();
        UpdateStepList(-1);
        RefreshPreview();
    }

    private void UpdateStepList(int select, bool keepEditor = false)
    {
        _suspendSync = true;
        _stepList.BeginUpdate();
        _stepList.Items.Clear();
        for (var i = 0; i < _rules.Steps.Count; i++)
        {
            _stepList.Items.Add(
                string.Create(CultureInfo.InvariantCulture, $"{i + 1,2}. {_rules.Steps[i].Describe()}"));
        }

        if (select >= 0 && select < _stepList.Items.Count)
        {
            _stepList.SelectedIndex = select;
        }

        _stepList.EndUpdate();
        _suspendSync = false;

        if (!keepEditor)
        {
            _editor.Bind(SelectedStep);
        }
    }

    private void LoadRules()
    {
        using var dialog = new OpenFileDialog
        {
            Title = "Load rules",
            Filter = "Rule sets (*.json)|*.json|All files (*.*)|*.*",
        };

        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            var loaded = RulesJson.Load(dialog.FileName);
            _rules.ApplyTo = loaded.ApplyTo;
            _rules.Sort = loaded.Sort;
            _rules.Steps.Clear();
            _rules.Steps.AddRange(loaded.Steps);
            SyncOptionBoxes();
            UpdateStepList(_rules.Steps.Count > 0 ? 0 : -1);
            RefreshPreview();
            SetStatus($"Loaded {_rules.Steps.Count} step(s) from {dialog.FileName}");
        }
        catch (Exception ex)
        {
            Warn("Could not load the rules file.\n\n" + ex.Message);
        }
    }

    private void SaveRules()
    {
        using var dialog = new SaveFileDialog
        {
            Title = "Save rules",
            Filter = "Rule sets (*.json)|*.json",
            FileName = "rules.json",
        };

        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            RulesJson.Save(dialog.FileName, _rules);
            SetStatus($"Saved rules to {dialog.FileName}");
        }
        catch (Exception ex)
        {
            Warn("Could not save the rules file.\n\n" + ex.Message);
        }
    }

    private void ExportPlan()
    {
        if (_plan is null)
        {
            Warn("There is no plan to export yet. Load a folder first.");
            return;
        }

        using var dialog = new SaveFileDialog
        {
            Title = "Export plan",
            Filter = "Plan files (*.json)|*.json",
            FileName = "plan.json",
        };

        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            PlanJson.Save(dialog.FileName, _plan);
            SetStatus($"Exported the plan to {dialog.FileName}");
        }
        catch (Exception ex)
        {
            Warn("Could not export the plan.\n\n" + ex.Message);
        }
    }

    // ---- preview ---------------------------------------------------------

    private void RefreshPreview()
    {
        _preview.BeginUpdate();
        _preview.Items.Clear();

        try
        {
            _plan = PlanBuilder.Build(_files, _rules, _folder);
        }
        catch (RulesFormatException ex)
        {
            _plan = null;
            _preview.EndUpdate();
            _summaryLabel.Text = "Rule error.";
            SetStatus(ex.Message);
            _applyButton.Enabled = false;
            return;
        }

        for (var i = 0; i < _plan.Items.Count; i++)
        {
            var item = _plan.Items[i];
            var row = new ListViewItem(new[]
            {
                (i + 1).ToString(CultureInfo.InvariantCulture),
                item.Original,
                item.Proposed,
                RenamePlan.Format(item.Status),
                item.Reason,
            });

            switch (item.Status)
            {
                case PlanStatus.Ok:
                    row.BackColor = OkBack;
                    break;
                case PlanStatus.Collision:
                    row.BackColor = CollisionBack;
                    break;
                case PlanStatus.Invalid:
                    row.BackColor = InvalidBack;
                    row.ForeColor = Color.FromArgb(150, 20, 30);
                    break;
                default:
                    row.ForeColor = SystemColors.GrayText;
                    break;
            }

            _preview.Items.Add(row);
        }

        _preview.EndUpdate();

        var s = _plan.Summary;
        _summaryLabel.Text = string.Create(
            CultureInfo.InvariantCulture,
            $"  {s.Total} file(s):  {s.Ok} to rename,  {s.Unchanged} unchanged,  {s.Collision} collision,  {s.Invalid} invalid");
        _applyButton.Enabled = s.Ok > 0 && !string.IsNullOrEmpty(_folder);
        _undoButton.Enabled = _undoStack.Count > 0;
    }

    // ---- apply / undo ----------------------------------------------------

    private void ApplyRename()
    {
        if (_plan is null || string.IsNullOrEmpty(_folder))
        {
            return;
        }

        var count = _plan.Summary.Ok;
        if (count == 0)
        {
            Warn("Nothing to do: no item has status \"ok\".");
            return;
        }

        var blocked = _plan.Summary.Collision + _plan.Summary.Invalid;
        var message = $"Rename {count} file(s) in\n{_folder}?";
        if (blocked > 0)
        {
            message += $"\n\n{blocked} item(s) are blocked (collision or invalid) and will be left alone.";
        }

        if (MessageBox.Show(this, message, "Apply rename", MessageBoxButtons.OKCancel, MessageBoxIcon.Question)
            != DialogResult.OK)
        {
            return;
        }

        var result = RenameExecutor.Apply(_plan, _folder);
        if (result.IsSuccess && result.Operation is not null)
        {
            _undoStack.Push(result.Operation);
            var history = RenameHistory.Record(result.Operation);
            SetStatus(history is null
                ? $"Renamed {result.Succeeded} file(s)."
                : $"Renamed {result.Succeeded} file(s). History: {history}");
        }
        else
        {
            Warn("The rename failed and was rolled back.\n\n" + string.Join("\n", result.Errors));
            SetStatus("Rename failed; nothing was changed.");
        }

        ReloadFolder();
    }

    private void UndoLast()
    {
        if (_undoStack.Count == 0)
        {
            return;
        }

        var operation = _undoStack.Peek();
        if (MessageBox.Show(
                this,
                $"Undo the last rename?\n\n{operation.Describe()}",
                "Undo",
                MessageBoxButtons.OKCancel,
                MessageBoxIcon.Question) != DialogResult.OK)
        {
            return;
        }

        var result = RenameExecutor.Undo(operation);
        if (result.IsSuccess)
        {
            _undoStack.Pop();
            SetStatus($"Restored {result.Succeeded} file name(s).");
        }
        else
        {
            Warn("Undo failed and was rolled back.\n\n" + string.Join("\n", result.Errors));
            SetStatus("Undo failed; nothing was changed.");
        }

        if (!string.Equals(operation.Directory, _folder, StringComparison.OrdinalIgnoreCase))
        {
            LoadFolder(operation.Directory);
        }
        else
        {
            ReloadFolder();
        }
    }

    // ---- misc ------------------------------------------------------------

    private void RunSelfTest()
    {
        var original = Console.Out;
        using var capture = new StringWriter();
        bool passed;
        try
        {
            Console.SetOut(capture);
            passed = Cli.SelfTest.Run();
        }
        finally
        {
            Console.SetOut(original);
        }

        MessageBox.Show(
            this,
            capture.ToString(),
            passed ? "Self-test passed" : "Self-test FAILED",
            MessageBoxButtons.OK,
            passed ? MessageBoxIcon.Information : MessageBoxIcon.Error);
    }

    private void ShowAbout() => MessageBox.Show(
        this,
        "Batch Rename Studio 1.0\n\n"
        + "Preview-first batch renaming for Windows.\n"
        + "The same planner drives this window and the headless mode:\n\n"
        + "  BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>",
        "About",
        MessageBoxButtons.OK,
        MessageBoxIcon.Information);

    private void SetStatus(string text) => _statusLabel.Text = "  " + text;

    private void Warn(string message)
        => MessageBox.Show(this, message, "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Warning);

    private static Label MakeLabel(string text, int width) => new()
    {
        Text = text,
        Width = width,
        AutoSize = false,
        TextAlign = ContentAlignment.MiddleLeft,
        Margin = new Padding(0, 6, 4, 0),
        Height = 24,
    };

    private static Button MakeButton(string text, Action onClick, int width, int height = 26)
    {
        var button = new Button { Text = text, Width = width, Height = height, Margin = new Padding(0, 1, 6, 1) };
        button.Click += (_, _) => onClick();
        return button;
    }
}

