const int leftMin = 360;
const int rightMin = 380;

void PlaceSplitter(object? sender, EventArgs e)
{
    Shown -= PlaceSplitter;
    try
    {
        if (split.Width < leftMin + rightMin + split.SplitterWidth)
        {
            return;
        }

        split.Panel1MinSize = leftMin;
        split.Panel2MinSize = rightMin;
        split.SplitterDistance = Math.Clamp(
            470,
            leftMin,
            split.Width - rightMin - split.SplitterWidth);
    }
    catch (InvalidOperationException)
    {
        // Layout was not ready; the default split is still usable.
    }
    catch (ArgumentException)
    {
        // Same.
    }
}

Shown += PlaceSplitter;
return split;

