using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The headless entry point.
/// <code>BatchRenameStudio.exe --plan --dir &lt;folder&gt; --rules &lt;rules.json&gt; --out &lt;plan.json&gt;</code>
/// Exit codes: 0 success, 2 usage or input error, 3 unexpected failure.
/// In <c>--plan</c> mode stdout carries exactly one summary line and nothing else, and no
/// file is ever renamed.
/// </summary>
internal static class CommandLine
{
    public const int ExitSuccess = 0;
    public const int ExitUsage = 2;
    public const int ExitFailure = 3;

    /// <summary>True when the arguments are meant for the console entry point rather than the GUI.</summary>
    public static bool IsCliInvocation(string[] args) => args.Any(a => a.StartsWith('-'));

    public static int Run(string[] args)
    {
        try
        {
            if (args.Any(a => a is "--help" or "-h" or "-?" or "/?"))
            {
                Console.Error.WriteLine(UsageText);
                return ExitSuccess;
            }

            if (args.Any(a => a is "--version"))
            {
                Console.Error.WriteLine("Batch Rename Studio 1.0.0");
                return ExitSuccess;
            }

            if (args.Any(a => a is "--selftest"))
            {
                return SelfTest.Run() ? ExitSuccess : ExitFailure;
            }

            if (!TryParse(args, out var options))
            {
                return ExitUsage;
            }

            if (options.Plan && options.Apply)
            {
                return Fail("--plan and --apply are mutually exclusive.");
            }

            if (options.Plan)
            {
                return RunPlan(options);
            }

            if (options.Apply)
            {
                return RunApply(options);
            }

            Console.Error.WriteLine("error: no mode given; expected --plan.");
            Console.Error.WriteLine(UsageText);
            return ExitUsage;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return ExitFailure;
        }
    }

    // ---- modes -----------------------------------------------------------

    private static int RunPlan(Options options)
    {
        if (options.Directory is null || options.Rules is null || options.Output is null)
        {
            Console.Error.WriteLine("error: --plan requires --dir, --rules and --out.");
            Console.Error.WriteLine(UsageText);
            return ExitUsage;
        }

        if (!TryLoad(options.Directory, options.Rules, out var plan, out var exitCode))
        {
            return exitCode;
        }

        PlanJson.Save(options.Output, plan!);

        var s = plan!.Summary;
        Console.Out.WriteLine(string.Create(
            CultureInfo.InvariantCulture,
            $"total={s.Total} ok={s.Ok} collision={s.Collision} unchanged={s.Unchanged} invalid={s.Invalid}"));
        Console.Out.Flush();
        return ExitSuccess;
    }

    /// <summary>
    /// Scriptable rename. Not part of the verified contract; it exists so the same rule sets
    /// can be run from a script. Requires --yes so a rename is never one typo away.
    /// </summary>
    private static int RunApply(Options options)
    {
        if (options.Directory is null || options.Rules is null)
        {
            return Fail("--apply requires --dir and --rules.");
        }

        if (!options.Yes)
        {
            return Fail("--apply renames files; add --yes to confirm.");
        }

        if (!TryLoad(options.Directory, options.Rules, out var plan, out var exitCode))
        {
            return exitCode;
        }

        var folder = Path.GetFullPath(options.Directory);
        var result = RenameExecutor.Apply(plan!, folder);
        if (!result.IsSuccess)
        {
            foreach (var error in result.Errors)
            {
                Console.Error.WriteLine("error: " + error);
            }

            Console.Error.WriteLine(result.RolledBack
                ? "error: the batch was rolled back; nothing changed."
                : "error: the batch failed.");
            return ExitFailure;
        }

        if (result.Operation is not null && options.Output is null)
        {
            RenameHistory.Record(result.Operation);
        }
        else if (result.Operation is not null)
        {
            PlanJson.Save(options.Output!, plan!);
            RenameHistory.Record(result.Operation);
        }

        var s = plan!.Summary;
        Console.Out.WriteLine(string.Create(
            CultureInfo.InvariantCulture,
            $"renamed={result.Succeeded} skipped={s.Total - result.Succeeded}"));
        Console.Out.Flush();
        return ExitSuccess;
    }

    private static bool TryLoad(string directory, string rulesPath, out RenamePlan? plan, out int exitCode)
    {
        plan = null;

        if (!Directory.Exists(directory))
        {
            exitCode = Fail($"folder not found: {directory}");
            return false;
        }

        if (!File.Exists(rulesPath))
        {
            exitCode = Fail($"rules file not found: {rulesPath}");
            return false;
        }

        try
        {
            plan = PlanBuilder.Build(directory, RulesJson.Load(rulesPath));
        }
        catch (RulesFormatException ex)
        {
            exitCode = Fail(ex.Message);
            return false;
        }

        exitCode = ExitSuccess;
        return true;
    }

    // ---- argument parsing ------------------------------------------------

    private sealed class Options
    {
        public bool Plan { get; set; }

        public bool Apply { get; set; }

        public bool Yes { get; set; }

        public string? Directory { get; set; }

        public string? Rules { get; set; }

        public string? Output { get; set; }
    }

    private static bool TryParse(string[] args, out Options options)
    {
        options = new Options();

        for (var i = 0; i < args.Length; i++)
        {
            switch (args[i])
            {
                case "--plan":
                    options.Plan = true;
                    break;

                case "--apply":
                    options.Apply = true;
                    break;

                case "--yes":
                    options.Yes = true;
                    break;

                case "--dir":
                    if (!TryTakeValue(args, ref i, "--dir", out var dir))
                    {
                        return false;
                    }

                    options.Directory = dir;
                    break;

                case "--rules":
                    if (!TryTakeValue(args, ref i, "--rules", out var rules))
                    {
                        return false;
                    }

                    options.Rules = rules;
                    break;

                case "--out":
                    if (!TryTakeValue(args, ref i, "--out", out var output))
                    {
                        return false;
                    }

                    options.Output = output;
                    break;

                default:
                    Console.Error.WriteLine($"error: unknown argument \"{args[i]}\".");
                    Console.Error.WriteLine(UsageText);
                    return false;
            }
        }

        return true;
    }

    private static bool TryTakeValue(string[] args, ref int i, string name, out string? value)
    {
        if (i + 1 >= args.Length)
        {
            Console.Error.WriteLine($"error: {name} requires a value.");
            value = null;
            return false;
        }

        value = args[++i];
        return true;
    }

    private static int Fail(string message)
    {
        Console.Error.WriteLine("error: " + message);
        return ExitUsage;
    }

    private const string UsageText = """
        Batch Rename Studio

          BatchRenameStudio.exe
              Launch the graphical rule editor.

          BatchRenameStudio.exe <folder>
              Launch the editor with <folder> already loaded.

          BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>
              Write the rename plan for <folder> and exit. Renames nothing.
              stdout receives one summary line: total=N ok=N collision=N unchanged=N invalid=N

          BatchRenameStudio.exe --apply --dir <folder> --rules <rules.json> --yes [--out <plan.json>]
              Rename the "ok" items of that same plan. --yes is required.
              stdout receives one summary line: renamed=N skipped=N

          BatchRenameStudio.exe --selftest
              Run the built-in semantics checks.

        Exit codes: 0 success, 2 usage or input error, 3 unexpected failure.
        """;
}

